const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.4.1",
  "engineVersion": "55ae170b1ced7fc6ed07a15f110549408c501bb3",
  "activeProvider": "postgresql",
  "inlineSchema": "// 쿠팡 광고 리포트 매니저 데이터 모델\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── 데이터 수집 열거형 ──────────────────────────────────────────────────────\n\nenum CollectionStatus {\n  PENDING\n  RUNNING\n  DOWNLOADING\n  PARSING\n  COMPLETED\n  FAILED\n}\n\n// ─── 실행 태스크 열거형 ──────────────────────────────────────────────────────\n\nenum ActionType {\n  REMOVE_KEYWORD\n  ADJUST_BID\n  PAUSE_CAMPAIGN\n  RESUME_CAMPAIGN\n  ADJUST_BUDGET\n}\n\nenum ExecutionStatus {\n  PENDING_APPROVAL\n  APPROVED\n  EXECUTING\n  COMPLETED\n  FAILED\n  ROLLED_BACK\n}\n\n// ─── AI 분석 열거형 ──────────────────────────────────────────────────────────\n\nenum AnalysisType {\n  DAILY_REVIEW\n  KEYWORD_AUDIT\n  BUDGET_OPTIMIZATION\n  CAMPAIGN_SCORING\n}\n\nenum AnalysisStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n}\n\n// ─── Workdeck OS 열거형 ───────────────────────────────────────────────────────\n\nenum SpaceType {\n  PERSONAL\n  ORGANIZATION\n}\n\nenum SpaceMemberRole {\n  OWNER\n  ADMIN\n  MEMBER\n}\n\n// 에이전트 승인 큐 액션 상태 (Phase 4)\nenum AgentActionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  EXECUTED\n  FAILED\n  EXPIRED\n}\n\n// 승인 요청 출처\nenum AgentActionSource {\n  MCP\n  WORKDECK_AGENT\n  WEB\n  SYSTEM\n}\n\n// ─── 발주 예측 열거형 ─────────────────────────────────────────────────────────\n\n// 발주 계획 상태\nenum ReorderPlanStatus {\n  DRAFT // 초안 — 자유 편집, 측정 안 함\n  FINALIZED // 예측 검증 시작(UI \"확정\") — 예측 동결 + 신뢰도 측정 대상. 직접 편집 불가(revert→새 revision)\n  CONSUMED // (폐기 예정) 레거시 — settle가 더는 이 상태로 전환하지 않음. 읽기 호환만 유지\n}\n\n// 확정 스냅샷 출처 — 진짜 확정 시점 값 vs 마이그 backfill 값 구분\nenum ReorderSnapshotSource {\n  LIVE // 확정 액션 시점에 동결된 실제 값\n  BACKFILLED // 마이그레이션이 당시 plan-item 현재값으로 채운 근사값\n}\n\n// 적중률 레코드 유효성 — revert/supersede 시 삭제 대신 무효화 (학습은 ACTIVE만)\nenum ReorderAccuracyValidity {\n  ACTIVE // 유효 — 학습/제안 집계에 사용\n  INVALIDATED // 무효 — 측정 근거 불충분/오류로 제외\n  SUPERSEDED // 대체됨 — 계획이 revert되어 새 revision으로 대체\n}\n\n// 옵션별 평가 진행 상태 (plan 단위 정산 전환을 대체)\nenum ReorderEvaluationStatus {\n  PENDING // 확정 전 또는 평가창 미경과\n  ELIGIBLE // 평가창 경과 — 정산 대기\n  MEASURED // 정산 완료 (accuracy 기록됨)\n  INVALIDATED // revert/supersede로 제외\n}\n\n// 발주 예측 모델 종류\nenum ReorderForecastModel {\n  SMA // 단순 이동평균\n  WMA // 가중 이동평균\n  HW // Holt-Winters (계절성)\n  CROSTON // Croston/SBA (간헐적 수요)\n  BAYES // Bayesian Poisson-Gamma (콜드스타트)\n  MANUAL // 사용자 직접 입력\n}\n\n// ─── 셀러 허브 열거형 ─────────────────────────────────────────────────────────\n\n// 프로모션 유형\nenum PromotionType {\n  NONE // 프로모션 없음\n  FLAT // 고정 할인 금액\n  PERCENT // 비율 할인\n  COUPON // 쿠폰 할인\n  MIN_PRICE // 최소 판매가 ceiling — column 할인 결과가 이 값보다 높으면 강제 인하\n}\n\n// 판매채널 상품 상태 — 시스템 재고 0일 때는 effective status가 SOLD_OUT으로 표시됨 (DB에는 저장 X).\nenum ProductListingStatus {\n  ACTIVE\n  SUSPENDED\n}\n\n// 상품 마스터 상태 — INACTIVE는 기존 이력은 보존하되 신규 작업 선택에서 제외.\nenum InvProductStatus {\n  ACTIVE\n  INACTIVE\n}\n\n// ─── 사용자 모델 (Supabase Auth와 연동) ──────────────────────────────────────\n\nmodel User {\n  id        String  @id // Supabase Auth UUID를 그대로 사용 (no default)\n  email     String  @unique\n  name      String?\n  avatarUrl String?\n\n  // 소유한 워크스페이스 (기존 — 점진 전환 기간 동안 유지)\n  workspace Workspace?\n\n  // Workdeck OS: 공간 멤버십\n  spaceMemberships SpaceMember[]\n\n  // 발주 계획 (작성자)\n  reorderPlans ReorderPlan[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 워크스페이스 (쿠팡 사업자 단위)\nmodel Workspace {\n  id   String @id @default(cuid())\n  name String // 쿠팡 사업자명\n\n  // 소유 사용자\n  ownerId String @unique\n  owner   User   @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n\n  // 연관 데이터\n  reportUploads   ReportUpload[]\n  adRecords       AdRecord[]\n  dailyMemos      DailyMemo[]\n  campaignMetas   CampaignMeta[]\n  keywordStatuses KeywordStatus[]\n  campaignTargets CampaignTarget[]\n  productStatuses ProductStatus[]\n\n  // AI 분석 리포트\n  analysisReports AnalysisReport[]\n\n  // 실행 태스크\n  executionTasks ExecutionTask[]\n  safetyLimits   SafetyLimits?\n\n  // 비즈니스 에이전트\n  businessAgent BusinessAgent?\n\n  // 학습형 분석 규칙\n  analysisRules AnalysisRule[]\n\n  // 분석 자동 스케줄\n  analysisSchedule AnalysisSchedule?\n\n  // 데이터 수집 관련\n  coupangCredential   CoupangCredential?\n  collectionSchedule  CollectionSchedule?\n  collectionRuns      CollectionRun[]\n  coupangBackfillJobs CoupangBackfillJob[]\n\n  // 재고 관리\n  inventoryUploads          InventoryUpload[]\n  inventoryRecords          InventoryRecord[]\n  inventoryExcludedProducts InventoryExcludedProduct[]\n  inventoryAnalyses         InventoryAnalysis[]\n\n  createdAt DateTime @default(now())\n}\n\n// 업로드 이력\nmodel ReportUpload {\n  id          String   @id @default(cuid())\n  fileName    String\n  uploadedAt  DateTime @default(now())\n  periodStart DateTime\n  periodEnd   DateTime\n\n  // 처리 결과 통계\n  totalRows     Int?\n  insertedRows  Int?\n  duplicateRows Int?\n  skippedRows   Int?\n\n  // 소속 워크스페이스\n  workspaceId String\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  // 이 업로드에서 파싱된 광고 데이터\n  adRecords AdRecord[]\n\n  @@index([workspaceId])\n}\n\n// 광고 데이터 행 (Excel 한 행 = 하나의 AdRecord)\nmodel AdRecord {\n  id           String   @id @default(cuid())\n  date         DateTime\n  adType       String // 광고유형 (예: 키워드 광고, 상품 광고)\n  campaignId   String\n  campaignName String\n  adGroup      String? // 광고그룹\n  placement    String? // 광고 노출 지면\n  productName  String? // 광고집행 상품명\n  optionId     String? // 광고집행 옵션ID\n  keyword      String? // 키워드 (없을 수 있음)\n\n  // 노출·클릭\n  impressions Int\n  clicks      Int\n  adCost      Decimal @db.Decimal(18, 2) // 광고비\n  ctr         Decimal @db.Decimal(10, 4) // 클릭률\n\n  // 1일 전환 지표\n  orders1d  Int\n  revenue1d Decimal @db.Decimal(18, 2) // 직접 전환매출액 (1일)\n  roas1d    Decimal @db.Decimal(10, 4) // 직접 광고수익률 (1일)\n\n  // NCA 공통 필드\n  material String? // 소재 (NCA: 소재 컬럼)\n\n  // NCA 동영상 지표 (없으면 null)\n  videoViews3s   Int? // 동영상 3초 조회\n  avgPlayTime    Decimal? @db.Decimal(10, 2) // 평균 재생 시간\n  videoViews25p  Int? // 25% 재생수\n  videoViews50p  Int? // 50% 재생수\n  videoViews75p  Int? // 75% 재생수\n  videoViews100p Int? // 100% 재생수\n  costPerView3s  Decimal? @db.Decimal(18, 2) // 동영상 3초 조회당 비용\n  engagements    Int? // 참여수\n  engagementRate Decimal? @db.Decimal(10, 4) // 참여율\n\n  // 소속 워크스페이스\n  workspaceId String\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  // 소속 업로드 이력\n  reportId String\n  report   ReportUpload @relation(fields: [reportId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, date, campaignId, adType, keyword, adGroup, optionId])\n  @@index([workspaceId, campaignId])\n  @@index([workspaceId, campaignId, date])\n  @@index([workspaceId, date])\n}\n\n// 캠페인 메타 (표시명 커스터마이징)\nmodel CampaignMeta {\n  id           String    @id @default(cuid())\n  workspaceId  String\n  campaignId   String\n  displayName  String\n  isCustomName Boolean   @default(false)\n  workspace    Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([workspaceId, campaignId])\n  @@index([workspaceId])\n}\n\n// 키워드 제거 상태 관리\nmodel KeywordStatus {\n  id          String    @id @default(cuid())\n  workspaceId String\n  campaignId  String\n  keyword     String\n  removedAt   DateTime?\n  removedMemo String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, campaignId, keyword])\n  @@index([workspaceId, campaignId])\n}\n\n// 캠페인 일 예산 / 목표 ROAS 설정 이력 (effectiveDate 기반)\nmodel CampaignTarget {\n  id            String   @id @default(cuid())\n  workspaceId   String\n  campaignId    String\n  effectiveDate DateTime @db.Date // 이 값이 적용되기 시작하는 날짜\n  dailyBudget   Int? // 일 예산 (원), null = 미설정\n  targetRoas    Float? // 목표 ROAS (%), null = 미설정\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, campaignId, effectiveDate])\n  @@index([workspaceId, campaignId, effectiveDate])\n}\n\n// 상품 제거 상태 관리\nmodel ProductStatus {\n  id          String    @id @default(cuid())\n  workspaceId String\n  campaignId  String\n  productName String\n  optionId    String    @default(\"\")\n  removedAt   DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, campaignId, productName, optionId])\n  @@index([workspaceId, campaignId])\n}\n\n// 일자별 메모 (캠페인별 광고 작업 이력)\nmodel DailyMemo {\n  id         String   @id @default(cuid())\n  campaignId String\n  date       DateTime\n  content    String\n\n  // 소속 워크스페이스\n  workspaceId String\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // 워크스페이스 + 캠페인 + 날짜 조합은 유일\n  @@unique([workspaceId, campaignId, date])\n  @@index([workspaceId, campaignId])\n}\n\n// ─── Workdeck OS 모델 ─────────────────────────────────────────────────────────\n\n// 공간 (개인 or 조직 테넌트)\nmodel Space {\n  id   String    @id @default(cuid())\n  name String\n  type SpaceType @default(PERSONAL)\n\n  members       SpaceMember[]\n  deckInstances DeckInstance[]\n\n  // 통합 재고 관리 (Inv)\n  invProducts         InvProduct[]\n  invLocations        InvStorageLocation[]\n  invMovements        InvMovement[]\n  invStockLevels      InvStockLevel[]\n  invImportHistories  InvImportHistory[]\n  invReconciliations  InvReconciliation[]\n  invLocationMappings InvLocationProductMap[]\n  invSettings         InvSettings?\n  invProductGroups    InvProductGroup[]\n\n  // 통합 배송 관리 (Del)\n  delShippingMethods      DelShippingMethod[]\n  delBatches              DelBatch[]\n  delOrders               DelOrder[]\n  delIntegrationHistories DelIntegrationHistory[]\n  delColumnMappingPresets DelColumnMappingPreset[]\n  channelProductAliases   ChannelProductAlias[]\n  delShippingMethodLabels DelShippingMethodLabel[]\n\n  // 셀러 허브 공용 (Seller Hub)\n  channels               Channel[]\n  channelTypeDefs        ChannelTypeDef[]\n  brands                 Brand[]\n  productPricingSettings ProductPricingSettings?\n  optionCodeAliases      SpaceOptionCodeAlias[]\n  productListings        ProductListing[]\n  channelStockMovements  ChannelStockMovement[]\n  channelProducts        ChannelProduct[]\n  productionRuns         ProductionRun[]\n  pricingScenarios       PricingScenario[]\n  adCampaignProductMaps  AdCampaignProductMap[]\n\n  // 발주 계획\n  reorderPlans ReorderPlan[]\n\n  // Slack 연동 (M3)\n  slackInstallation SlackInstallation?\n\n  // 온보딩 카드 닫힘 시각 (사용자가 명시적으로 X 클릭 시 기록)\n  onboardingDismissedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // ─── Sales Content Deck ───\n  products             Product[]\n  personas             Persona[]\n  brandProfile         BrandProfile?\n  workspaceAiCredits   WorkspaceAiCredit[]\n  imageGenerationLogs  ImageGenerationLog[]\n  textGenerationLogs   TextGenerationLog[]\n  ideations            Ideation[]\n  templates            Template[]\n  salesContentChannels SalesContentChannel[]\n  contents             Content[]\n  contentAssets        ContentAsset[]\n  contentVersions      ContentVersion[]\n  contentDeployments   ContentDeployment[]\n  contentClickEvents   ContentClickEvent[]\n  channelCredentials   ChannelCredential[]\n  salesContentJobs     SalesContentJob[]\n  deploymentMetrics    DeploymentMetric[]\n  improvementRules     ImprovementRule[]\n\n  // ─── 재무 관리 Deck (Finance) ───\n  finAccounts         FinAccount[]\n  finLiabilities      FinLiability[]\n  finCategories       FinCategory[]\n  finClassRules       FinClassRule[]\n  finMappingPresets   FinMappingPreset[]\n  finImports          FinImport[]\n  finStagedRows       FinStagedRow[]\n  finTransactions     FinTransaction[]\n  finBalanceSnapshots FinBalanceSnapshot[]\n\n  // ─── 채용 관리 Deck (Hiring) ───\n  hiringStores           HiringStore[]\n  hiringPositions        HiringPosition[]\n  hiringPostings         HiringPosting[]\n  hiringPostingPositions HiringPostingPosition[]\n  hiringContents         HiringContent[]\n  hiringDetailTemplates  HiringDetailTemplate[]\n  hiringApplications     HiringApplication[]\n  hiringBlacklists       HiringBlacklist[]\n  hiringMessageTemplates HiringMessageTemplate[]\n\n  // ─── 블로그 운영 Deck (Blog Ops) ───\n  boProducts           BoProduct[]\n  boIdeations          BoIdeation[]\n  boMaterials          BoMaterial[]\n  boPosts              BoPost[]\n  boPostVersions       BoPostVersion[]\n  boChannels           BoChannel[]\n  boPostVariants       BoPostVariant[]\n  boDeployments        BoDeployment[]\n  boJobs               BoJob[]\n  boChannelCredentials BoChannelCredential[]\n\n  // ─── 에이전트 승인 큐 (Agent) ───\n  agentPendingActions AgentPendingAction[]\n\n  // ─── 하이브리드 workdeck 에이전트 (M4) ───\n  agentToggle    SpaceAgent?\n  agentLlmUsages AgentLlmUsage[]\n\n  // ─── 구독·결제 (Billing) ───\n  subscription   SpaceSubscription?\n  billingMethods BillingMethod[]\n  billingCharges BillingCharge[]\n}\n\n// 공간 멤버십 + 역할\nmodel SpaceMember {\n  id      String          @id @default(cuid())\n  spaceId String\n  userId  String\n  role    SpaceMemberRole @default(MEMBER)\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([spaceId, userId])\n  @@index([userId])\n}\n\n// 에이전트 승인 큐 — MCP/워크덱 에이전트의 상태 변경(write) 요청을 승인부 실행한다.\n// 조회는 자유, 변경은 이 큐에 PENDING으로 쌓이고 ADMIN 승인 시 동기 실행된다.\nmodel AgentPendingAction {\n  id          String            @id @default(cuid())\n  spaceId     String\n  deckKey     String // \"finance\" | \"seller-hub\" | \"coupang-ads\"\n  actionType  String // ActionDefinition.actionType, 예: \"finance.transaction.reclassify\"\n  payload     Json // 액션 파라미터 (paramsSchema로 검증된 값)\n  summary     String // 사람이 읽는 한 줄 요약\n  beforeState Json? // 실행 전 스냅샷 (diff·롤백 참고용)\n  source      AgentActionSource\n  requestedBy String // 요청자 User.id (또는 워커/시스템 식별자)\n\n  status     AgentActionStatus @default(PENDING)\n  expiresAt  DateTime // createPendingAction에서 now+72h로 설정 (앱 계산)\n  decidedBy  String? // 승인/거부한 User.id\n  decidedAt  DateTime?\n  executedAt DateTime?\n  result     Json? // execute 성공 결과\n  error      String? // execute 실패 메시지\n\n  idempotencyKey String? @unique // 재시도 멱등 — 동일 키 재요청 시 기존 액션 반환\n  slackChannelId String? // Phase 6 Slack 연동 예약\n  slackMessageTs String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  @@index([spaceId, status, createdAt])\n  @@index([status, expiresAt])\n}\n\n// Space별 workdeck 에이전트 활성 토글. 레코드 없으면 앱에서 기본 활성으로 취급한다.\nmodel SpaceAgent {\n  id       String  @id @default(cuid())\n  spaceId  String  @unique\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n}\n\n// LLM 사용량 일일 집계 — Space별 rate limit. date는 KST \"YYYY-MM-DD\".\nmodel AgentLlmUsage {\n  id           String @id @default(cuid())\n  spaceId      String\n  date         String // KST YYYY-MM-DD\n  requestCount Int    @default(0)\n  inputTokens  Int    @default(0)\n  outputTokens Int    @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  @@unique([spaceId, date])\n}\n\n// Slack 스레드 단위 대화 세션. messages는 최근 20턴 [{ role, content }] JSON.\n// (Space Cascade는 걸지 않는다 — TTL cron이 정리하고, Slack 좌표만으로 조회한다.)\nmodel AgentConversation {\n  id        String @id @default(cuid())\n  spaceId   String\n  channelId String\n  threadTs  String\n  messages  Json // [{ role: \"user\"|\"assistant\", content: ... }]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([channelId, threadTs])\n  @@index([updatedAt])\n}\n\n// Slack 워크스페이스 설치 (Space당 1개, Slack team당 1개).\n// bot 토큰은 AES-256-CBC로 암호화해 저장한다(ENCRYPTION_KEY).\nmodel SlackInstallation {\n  id          String   @id @default(cuid())\n  spaceId     String   @unique\n  teamId      String   @unique // Slack workspace ID (T...)\n  teamName    String?\n  botUserId   String\n  botToken    String // AES-256-CBC hex 암호문 (xoxb-)\n  botTokenIv  String // hex IV\n  scope       String?\n  installedBy String // 설치한 User.id\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  space    Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channels SpaceSlackChannel[]\n}\n\n// Space별 용도 채널 (M3: kind=\"approvals\" 승인 알림 채널).\nmodel SpaceSlackChannel {\n  id          String   @id @default(cuid())\n  spaceId     String\n  channelId   String // C...\n  channelName String?\n  kind        String   @default(\"approvals\")\n  createdAt   DateTime @default(now())\n\n  installation SlackInstallation @relation(fields: [spaceId], references: [spaceId], onDelete: Cascade)\n\n  @@unique([spaceId, kind])\n  @@index([channelId])\n}\n\n// 카드 앱 카탈로그 (전역 정의)\nmodel DeckApp {\n  id          String  @id // \"coupang-ads\", \"osmu\", \"commerce-ops\"\n  name        String\n  description String?\n  isActive    Boolean @default(true)\n\n  instances DeckInstance[]\n}\n\n// Space에서 활성화된 카드 인스턴스\nmodel DeckInstance {\n  id                 String  @id @default(cuid())\n  spaceId            String\n  deckAppId          String\n  isActive           Boolean @default(true)\n  // Deck 단위 Slack 알림 토글 — false면 이 Deck의 모든 알림(레거시 포함) 발송을 차단한다.\n  slackNotifyEnabled Boolean @default(true)\n  // 이벤트 단위 알림 토글 — 비활성 이벤트만 { \"<eventKey>\": false } 로 기록(미기재=on).\n  // 레지스트리: src/lib/slack/notification-events.ts (togglable 이벤트만 저장 대상).\n  slackNotifyEvents  Json?\n\n  space   Space   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  deckApp DeckApp @relation(fields: [deckAppId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@unique([spaceId, deckAppId])\n  @@index([spaceId])\n}\n\n// ─── 데이터 수집 모델 ────────────────────────────────────────────────────────\n\n// 쿠팡 로그인 자격증명 (워크스페이스당 1개)\nmodel CoupangCredential {\n  id                 String    @id @default(cuid())\n  workspaceId        String    @unique\n  loginId            String\n  loginPassword      String\n  encryptionIv       String\n  isActive           Boolean   @default(true)\n  // 판매분석(VENDOR) 수집 허가 — isActive(크레덴셜 유효)와 의미 분리.\n  // false 면 워커가 inventory_health 만 수집하고 VENDOR(로켓그로스 일별 판매)는 건너뛴다.\n  collectVendorSales Boolean   @default(true)\n  lastLoginAt        DateTime?\n  lastError          String?\n  workspace          Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n}\n\n// 자동 수집 스케줄 (워크스페이스당 1개)\nmodel CollectionSchedule {\n  id             String    @id @default(cuid())\n  workspaceId    String    @unique\n  enabled        Boolean   @default(true)\n  cronExpression String    @default(\"30 12 * * *\")\n  timezone       String    @default(\"Asia/Seoul\")\n  workspace      Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n}\n\nenum CoupangBackfillStatus {\n  PENDING\n  RUNNING\n  DONE\n  FAILED\n  CANCELLED\n}\n\n// 콜드스타트 판매분석 백필 잡 — 웹은 Wing 직접 수집 불가하므로 워커가 폴링해 실행.\n// 워커: 과거 days 일 VENDOR 수집 → coupang-sales-sync range 변환(step-2) 체이닝.\nmodel CoupangBackfillJob {\n  id            String                @id @default(cuid())\n  workspaceId   String\n  days          Int // 과거 N일 (어제부터 역순). range 잡이면 endDate−startDate+1(포함).\n  // range 백필(캘린더 특정 구간). 둘 다 null이면 days 기반(어제부터 역순) 잡.\n  startDate     String? // 수집 시작일 KST YYYY-MM-DD (oldest)\n  endDate       String? // 수집 종료일 KST YYYY-MM-DD (newest, 보통 어제)\n  trigger       String                @default(\"backfill\") // backfill(UI 과거수집) | scheduled(매일 cron)\n  status        CoupangBackfillStatus @default(PENDING)\n  claimedAt     DateTime?\n  claimedBy     String?\n  completedAt   DateTime?\n  collected     Int                   @default(0) // 적재된 일자 수\n  converted     Int                   @default(0) // OUTBOUND 변환된 일자 수\n  // 이력 요약 (수집 결과 가시화) — 잡 전체 누적\n  duplicateRows Int                   @default(0) // 중복으로 건너뛴 VENDOR 행 수\n  outboundCount Int                   @default(0) // 생성/갱신된 OUTBOUND(재고차감) 이동 건수\n  revenueSum    Decimal               @default(0) @db.Decimal(18, 2) // 매출 합\n  orderSum      Int                   @default(0) // 주문 합\n  salesQtySum   Int                   @default(0) // 판매량 합\n  error         String?\n  workspace     Workspace             @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n\n  @@index([status, createdAt])\n  @@index([workspaceId, status])\n}\n\n// 수집 실행 이력\nmodel CollectionRun {\n  id               String           @id @default(cuid())\n  workspaceId      String\n  status           CollectionStatus @default(PENDING)\n  triggeredBy      String\n  startedAt        DateTime?\n  completedAt      DateTime?\n  error            String?\n  uploadId         String?\n  // 수동 수집 작업 스코프 — 어떤 작업을 실행할지. 자동(scheduled)은 둘 다 true(전체).\n  // 판매(VENDOR)는 수동 수집에서 항상 제외되므로 별도 필드 없음(자동 cron 전용).\n  collectAds       Boolean          @default(true) // 광고 데이터 수집\n  collectInventory Boolean          @default(true) // 재고현황(HEALTH) 수집\n  workspace        Workspace        @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt        DateTime         @default(now())\n\n  @@index([workspaceId, status])\n  @@index([workspaceId, createdAt])\n}\n\n// ─── AI 분석 리포트 ─────────────────────────────────────────────────────────\n\nmodel AnalysisReport {\n  id          String         @id @default(cuid())\n  workspaceId String\n  periodStart DateTime\n  periodEnd   DateTime\n  reportType  AnalysisType\n  summary     String         @db.Text\n  suggestions Json\n  metadata    Json?\n  status      AnalysisStatus @default(PENDING)\n  triggeredBy String         @default(\"manual\")\n  createdAt   DateTime       @default(now())\n  workspace   Workspace      @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, createdAt])\n}\n\n// ─── 반자동 실행 인프라 ───────────────────────────────────────────────────────\n\n// 실행 태스크 (AI 제안 → 승인 → 실행 흐름)\nmodel ExecutionTask {\n  id               String          @id @default(cuid())\n  workspaceId      String\n  analysisReportId String?\n  actionType       ActionType\n  campaignId       String\n  target           String\n  params           Json\n  status           ExecutionStatus @default(PENDING_APPROVAL)\n  beforeState      Json?\n  afterState       Json?\n  approvedAt       DateTime?\n  approvedBy       String?\n  executedAt       DateTime?\n  error            String?\n  workspace        Workspace       @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt        DateTime        @default(now())\n  updatedAt        DateTime        @updatedAt\n\n  @@index([workspaceId, status])\n}\n\n// 안전 제한 설정 (워크스페이스당 1개)\nmodel SafetyLimits {\n  id                  String    @id @default(cuid())\n  workspaceId         String    @unique\n  maxBidChangePct     Int       @default(30)\n  maxKeywordsPerBatch Int       @default(20)\n  maxBudgetChangePct  Int       @default(50)\n  requireApproval     Boolean   @default(true)\n  workspace           Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n}\n\n// 학습형 분석 규칙 (사용자/모델/시스템이 추가한 분석 기준)\nmodel AnalysisRule {\n  id           String    @id @default(cuid())\n  workspaceId  String\n  rule         String    @db.Text\n  source       String // \"user\" | \"model\" | \"system\"\n  isActive     Boolean   @default(true)\n  appliedCount Int       @default(0)\n  workspace    Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([workspaceId, isActive])\n}\n\n// 분석 자동 스케줄 (워크스페이스당 1개)\nmodel AnalysisSchedule {\n  id                     String    @id @default(cuid())\n  workspaceId            String    @unique\n  enabled                Boolean   @default(true)\n  intervalDays           Int       @default(7)\n  analysisHour           Int?\n  triggerAfterCollection Boolean   @default(false)\n  slackNotify            Boolean   @default(true)\n  lastAnalyzedAt         DateTime?\n  workspace              Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  createdAt              DateTime  @default(now())\n  updatedAt              DateTime  @updatedAt\n}\n\n// 비즈니스 에이전트 (의식주의 Slack 에이전트)\nmodel BusinessAgent {\n  id             String     @id @default(cuid())\n  workspaceId    String     @unique\n  slackChannelId String?\n  slackBotToken  String?\n  isActive       Boolean    @default(true)\n  lastActiveAt   DateTime?\n  workspace      Workspace  @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  logs           AgentLog[]\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n}\n\nmodel AgentLog {\n  id        String        @id @default(cuid())\n  agentId   String\n  type      String // command, notification, error\n  command   String? // 사용자 입력 명령 (예: \"상태\", \"분석\")\n  response  String? // 에이전트 응답 요약\n  channel   String? // Slack 채널 ID\n  agent     BusinessAgent @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  createdAt DateTime      @default(now())\n\n  @@index([agentId, createdAt(sort: Desc)])\n}\n\n// ─── 워커 헬스체크 ────────────────────────────────────────────\n\n// 워커 프로세스 heartbeat — 서비스별 마지막 핑 시각.\n// cron이 이 값을 보고 워커 다운을 감지하여 Slack 알림한다.\nmodel WorkerHeartbeat {\n  id         String   @id @default(cuid())\n  service    String   @unique // 예: \"inventory-collector\"\n  lastPingAt DateTime\n  metadata   Json?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\n// ─── 재고 관리 ────────────────────────────────────────────────\n\n// 재고 엑셀 업로드 이력\nmodel InventoryUpload {\n  id           String   @id @default(cuid())\n  fileName     String\n  fileType     String // INVENTORY_HEALTH | VENDOR_ITEM_METRICS\n  uploadedAt   DateTime @default(now())\n  snapshotDate DateTime // 데이터 기준일\n  totalRows    Int?\n  insertedRows Int?\n\n  workspaceId String\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  inventoryRecords InventoryRecord[]\n\n  @@index([workspaceId])\n}\n\n// 재고 / 상품 성과 레코드\nmodel InventoryRecord {\n  id           String   @id @default(cuid())\n  workspaceId  String\n  snapshotDate DateTime\n  fileType     String // INVENTORY_HEALTH | VENDOR_ITEM_METRICS\n\n  // 상품 식별\n  productId   String // 등록상품ID\n  optionId    String // 옵션ID\n  skuId       String? // SKU ID\n  productName String\n  optionName  String?\n  category    String?\n\n  // 재고 (inventory_health)\n  availableStock     Int? // 판매가능재고\n  inboundStock       Int? // 입고예정재고\n  productGrade       String? // 상품등급 (NEW 등)\n  restockQty         Int? // 추가입고 추천수량\n  restockDate        String? // 추가입고날짜\n  estimatedDepletion String? // 재고예상 소진일\n  storageFee         Int? // 이번달 누적보관료\n  isItemWinner       Boolean? // 아이템위너 여부\n  returns30d         Int? // 고객반품 30일\n\n  // 매출/판매\n  revenue7d   Decimal? @db.Decimal(18, 2)\n  revenue30d  Decimal? @db.Decimal(18, 2)\n  salesQty7d  Int?\n  salesQty30d Int?\n  orderCount  Int? // VENDOR_ITEM_METRICS '주문' 컬럼\n\n  // vendor_item_metrics 전용\n  fulfillmentType String? // 판매방식: \"로켓그로스\" | \"판매자배송\"\n  visitors        Int?\n  views           Int?\n  cartAdds        Int?\n  conversionRate  Decimal? @db.Decimal(10, 4) // 구매전환율 %\n  itemWinnerRate  Decimal? @db.Decimal(10, 4) // 아이템위너 비율 %\n  totalRevenue    Decimal? @db.Decimal(18, 2)\n  totalSales      Int?\n  totalCancelAmt  Decimal? @db.Decimal(18, 2)\n  totalCancelled  Int?\n\n  // 보관기간별 재고\n  stock1to30d    Int?\n  stock31to45d   Int?\n  stock46to60d   Int?\n  stock61to120d  Int?\n  stock121to180d Int?\n  stock181plusD  Int?\n\n  workspace Workspace       @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  uploadId  String\n  upload    InventoryUpload @relation(fields: [uploadId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, snapshotDate, productId, optionId, fileType])\n  @@index([workspaceId, snapshotDate])\n  @@index([workspaceId, productName])\n}\n\n// 재고 관리 제외 옵션\nmodel InventoryExcludedProduct {\n  id          String   @id @default(cuid())\n  workspaceId String\n  productId   String\n  optionId    String\n  excludedAt  DateTime @default(now())\n  reason      String?\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, optionId])\n  @@index([workspaceId])\n}\n\n// 재고 분석 결과\nmodel InventoryAnalysis {\n  id           String   @id @default(cuid())\n  workspaceId  String\n  snapshotDate DateTime\n  analysedAt   DateTime @default(now())\n  triggeredBy  String   @default(\"manual\")\n\n  results          Json\n  shortageCount    Int  @default(0)\n  returnRateCount  Int  @default(0)\n  storageFeeCount  Int  @default(0)\n  winnerIssueCount Int  @default(0)\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, analysedAt(sort: Desc)])\n}\n\n// ─── 통합 재고 관리 (Inv) ─────────────────────────────────────────────────────\n\nenum InvMovementType {\n  INBOUND\n  OUTBOUND\n  RETURN\n  TRANSFER\n  ADJUSTMENT\n}\n\nenum InvReconciliationStatus {\n  PENDING\n  PARTIAL\n  APPLIED\n  CONFIRMED\n  CANCELLED\n}\n\nenum InvStorageLocationType {\n  OWN\n  THIRD_PARTY\n  STORE\n}\n\n// 상품 그룹 (카테고리)\nmodel InvProductGroup {\n  id      String @id @default(cuid())\n  spaceId String\n  name    String\n\n  space    Space        @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  products InvProduct[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n}\n\n// 상품 (옵션 단위로 관리)\nmodel InvProduct {\n  id      String           @id @default(cuid())\n  spaceId String\n  name    String // 공식 상품명 — 판매채널 노출명 (필수)\n  code    String? // 상품 코드 (space 내 unique, null 허용)\n  groupId String // 카테고리 필수 (non-null)\n  status  InvProductStatus @default(ACTIVE)\n\n  // 셀러 허브 확장 필드 (모두 nullable)\n  brandId            String?\n  internalName       String? // 관리 상품명 — 내부 식별용. 비어있으면 표시 시 name으로 fallback\n  nameEn             String?\n  manufacturer       String?\n  manufactureCountry String?\n  manufactureDate    DateTime?\n  features           Json?\n  certifications     Json?\n  msrp               Decimal?  @db.Decimal(18, 2)\n  description        String?\n  optionAttributes   Json? // 예: [{name:\"사이즈\",values:[\"S\",\"M\",\"L\"]}]\n\n  // 발주 라운딩 단위 (10 = 10단위 라운딩, 100 = 100단위 등)\n  reorderRoundUnit Int @default(10)\n\n  // 공급원가를 완료(입고완료) 생산 차수 가중평균 단가로 파생 표시할지 여부 (값 복사 없음)\n  useProductionCost Boolean @default(false)\n\n  space            Space                  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  group            InvProductGroup        @relation(fields: [groupId], references: [id], onDelete: Restrict)\n  brand            Brand?                 @relation(fields: [brandId], references: [id], onDelete: SetNull)\n  options          InvProductOption[]\n  reorderConfig    InvReorderConfig?\n  reorderPlanItems ReorderPlanItem[]\n  reorderPlans     ReorderPlan[]\n  adCampaignMaps   AdCampaignProductMap[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, code])\n  @@index([spaceId])\n  @@index([groupId])\n  @@index([brandId])\n}\n\n// 쿠팡 광고 캠페인 ↔ 내부 상품 귀속 매핑.\n//\n// AdRecord 는 Workspace 스코프이고 optionId 가 쿠팡 외부 옵션ID(예: 92143176219)라\n// 내부 InvProductOption 과 직접 FK 가 없다. 외부 optionId 브리지\n// (external-option-bridge.ts)로 옵션 단위 귀속이 되는 광고비는 그쪽이 먼저 처리하고,\n// 남은 캠페인 광고비를 이 표로 상품 단위 귀속한다. 상품 내 옵션 배분은 기간 매출 비례.\n//\n// 한 캠페인이 여러 상품을 담을 수 있어 (campaignId, productId) 다대다를 행으로 표현한다.\n// 어느 쪽으로도 귀속되지 않은 광고비는 unallocatedAdCost 로 반환한다(추정 배분 금지).\nmodel AdCampaignProductMap {\n  id         String  @id @default(cuid())\n  spaceId    String\n  campaignId String // 쿠팡 캠페인 ID (AdRecord.campaignId)\n  productId  String\n  memo       String?\n\n  space   Space      @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  product InvProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, campaignId, productId])\n  @@index([spaceId])\n  @@index([spaceId, campaignId])\n  @@index([productId])\n}\n\n// 상품 옵션\nmodel InvProductOption {\n  id        String  @id @default(cuid())\n  productId String\n  name      String\n  sku       String?\n\n  // 셀러 허브 확장 필드 (모두 nullable)\n  costPrice       Decimal? @db.Decimal(18, 2)\n  costVatIncluded Boolean  @default(false) // 공급원가 입력값에 VAT 포함 여부(ex-VAT 파생용)\n  retailPrice     Decimal? @db.Decimal(18, 2)\n  sizeLabel       String?\n  setSizeLabel    String?\n  attributeValues Json? // 예: {\"사이즈\":\"S\",\"색상\":\"파랑\"}\n\n  // 안전재고 (옵션 단위 단일 진입점) — 재고 상태 판정에 사용\n  safetyStockQty Int @default(0)\n\n  // 소프트삭제: 생산 차수·발주 등 연결 기록이 있는 옵션을 삭제할 때 row를 남겨 값을 보존한다.\n  // 연결이 없으면 완전삭제, 있으면 deletedAt만 채운다. 목록/피커는 deletedAt: null로 필터.\n  deletedAt DateTime?\n\n  product              InvProduct                       @relation(fields: [productId], references: [id], onDelete: Cascade)\n  movements            InvMovement[]\n  stockLevels          InvStockLevel[]\n  locationMappingItems InvLocationProductMapItem[]\n  productionRunItems   ProductionRunItem[]\n  pricingScenarioItems PricingScenarioItem[]\n  delOrderItems        DelOrderItem[]\n  channelAliases       ChannelProductAlias[]\n  aliasFulfillments    ChannelProductAliasFulfillment[]\n  shippingLabels       DelShippingMethodLabel[]\n  listingItems         ProductListingItem[]\n  fulfillments         DelOrderItemFulfillment[]\n  reorderPlanItems     ReorderPlanItem[]\n  reorderAccuracies    ReorderPlanAccuracy[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([productId])\n  @@index([deletedAt])\n}\n\n// 보관 장소\nmodel InvStorageLocation {\n  id       String                 @id @default(cuid())\n  spaceId  String\n  name     String\n  type     InvStorageLocationType @default(OWN)\n  isActive Boolean                @default(true)\n\n  // 외부 데이터 소스 자동 연결 (예: 쿠팡 로켓그로스 자동 분배 대상 위치)\n  // 값 예: 'coupang_rocket_growth'. 한 space 안에서 동일 source는 1개 위치만 가능.\n  externalSource         String?\n  externalIntegrationKey String?\n\n  space                 Space                   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  stockLevels           InvStockLevel[]\n  movements             InvMovement[]           @relation(\"MovementLocation\")\n  incomingTransfers     InvMovement[]           @relation(\"MovementToLocation\")\n  locationMappings      InvLocationProductMap[]\n  reconciliations       InvReconciliation[]\n  settingsDefault       InvSettings[]           @relation(\"DefaultLocation\")\n  productionRunStockIns ProductionRun[]         @relation(\"ProductionRunStockInLocation\")\n  reorderPlans          ReorderPlan[] // 연동위치 세트 발주 계획의 대상 위치\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, externalSource])\n  @@index([spaceId])\n  @@index([spaceId, type])\n}\n\n// 재고 이동 원장 (불변 레코드)\nmodel InvMovement {\n  id         String @id @default(cuid())\n  spaceId    String\n  optionId   String\n  locationId String\n\n  toLocationId    String? // TRANSFER 전용\n  channelId       String? // OUTBOUND 전용 (셀러 허브 공용 Channel FK)\n  type            InvMovementType\n  quantity        Int\n  movementDate    DateTime\n  orderDate       DateTime? // OUTBOUND 전용\n  reason          String? // ADJUSTMENT 시 필수 (앱 레벨 검증)\n  referenceId     String? // 연관 이동 또는 조정 ID (import 멱등: import:dh:<contentHash>)\n  importHistoryId String?\n  delBatchId      String? // 배송 이력 이전으로 생성된 경우 출처 묶음. 묶음 삭제 시 cascade.\n\n  space         Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  option        InvProductOption    @relation(fields: [optionId], references: [id], onDelete: Cascade)\n  location      InvStorageLocation  @relation(\"MovementLocation\", fields: [locationId], references: [id], onDelete: Cascade)\n  toLocation    InvStorageLocation? @relation(\"MovementToLocation\", fields: [toLocationId], references: [id], onDelete: SetNull)\n  channel       Channel?            @relation(fields: [channelId], references: [id], onDelete: SetNull)\n  importHistory InvImportHistory?   @relation(fields: [importHistoryId], references: [id], onDelete: SetNull)\n  delBatch      DelBatch?           @relation(fields: [delBatchId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId])\n  @@index([optionId])\n  @@index([locationId])\n  @@index([spaceId, movementDate])\n  @@index([delBatchId])\n}\n\n// 현재 재고 수준 (옵션 × 장소)\nmodel InvStockLevel {\n  id         String @id @default(cuid())\n  spaceId    String\n  optionId   String\n  locationId String\n  quantity   Int    @default(0) // 음수 가능\n\n  space    Space              @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  option   InvProductOption   @relation(fields: [optionId], references: [id], onDelete: Cascade)\n  location InvStorageLocation @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([optionId, locationId])\n  @@index([spaceId])\n}\n\n// 상품별 발주 예측 설정 — 한 상품의 모든 옵션이 동일한 리드타임/분석기간을 공유.\n// 안전재고는 옵션 단위(InvProductOption.safetyStockQty)에서 관리한다.\nmodel InvReorderConfig {\n  id                 String @id @default(cuid())\n  productId          String @unique\n  leadTimeDays       Int    @default(7)\n  analysisWindowDays Int    @default(90)\n\n  product InvProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n}\n\n// 대량 가져오기 이력\nmodel InvImportHistory {\n  id          String @id @default(cuid())\n  spaceId     String\n  fileName    String\n  fileType    String // \"EXCEL\" | \"CSV\"\n  totalRows   Int\n  successRows Int\n  errorRows   Int\n  errors      Json? // 행 단위 에러 상세\n\n  space     Space         @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  movements InvMovement[]\n\n  importedAt DateTime @default(now())\n\n  @@index([spaceId])\n}\n\n// 파일 기반 재고 대사 이력\nmodel InvReconciliation {\n  id            String                  @id @default(cuid())\n  spaceId       String\n  locationId    String\n  fileName      String\n  snapshotDate  DateTime\n  status        InvReconciliationStatus @default(PENDING)\n  matchResults  Json // 매칭/차이 상세\n  totalItems    Int\n  matchedItems  Int\n  adjustedItems Int                     @default(0)\n\n  space    Space              @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  location InvStorageLocation @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  createdAt   DateTime  @default(now())\n  confirmedAt DateTime?\n\n  @@index([spaceId])\n}\n\n// 보관 장소별 외부 상품 코드 매핑 (1:N — 외부코드 1개 → 내부 옵션 N개)\nmodel InvLocationProductMap {\n  id         String @id @default(cuid())\n  spaceId    String\n  locationId String\n\n  externalCode       String // 보관 장소의 상품 코드/ID\n  externalName       String? // 보관 장소의 상품명 (참조용)\n  externalOptionName String? // 보관 장소의 옵션명 (참조용)\n\n  items InvLocationProductMapItem[]\n\n  space    Space              @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  location InvStorageLocation @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([locationId, externalCode])\n  @@index([spaceId])\n}\n\n// 매핑 아이템 — 외부코드 하나에 여러 내부 옵션 + 수량 비율\nmodel InvLocationProductMapItem {\n  id       String @id @default(cuid())\n  mapId    String\n  optionId String\n  quantity Int    @default(1)\n\n  map    InvLocationProductMap @relation(fields: [mapId], references: [id], onDelete: Cascade)\n  option InvProductOption      @relation(fields: [optionId], references: [id], onDelete: Cascade)\n\n  @@unique([mapId, optionId])\n  @@index([optionId])\n}\n\n// 공간별 재고 덱 설정\nmodel InvSettings {\n  id                String  @id @default(cuid())\n  spaceId           String  @unique\n  defaultLocationId String?\n  slackWebhookUrl   String?\n  preferences       Json    @default(\"{}\")\n\n  space           Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  defaultLocation InvStorageLocation? @relation(\"DefaultLocation\", fields: [defaultLocationId], references: [id], onDelete: SetNull)\n\n  @@index([spaceId])\n}\n\n// ─── 통합 배송 관리 (Del) ─────────────────────────────────────────────────────\n\nenum DelBatchStatus {\n  DRAFT\n  COMPLETED\n}\n\n// 배치 출처 — 수동 등록 vs 과거 이력 이전(import).\n// IMPORT 묶음은 재고를 차감하지 않는 과거 이력이며,\n// 미래에 \"완료→OUTBOUND 자동생성\" 연동이 추가되어도 재처리 대상에서 제외해야 한다.\nenum DelBatchSource {\n  MANUAL\n  IMPORT\n}\n\n// 배송 방식 (택배사 + 파일 포맷)\nmodel DelShippingMethod {\n  id               String  @id @default(cuid())\n  spaceId          String\n  name             String\n  isActive         Boolean @default(true)\n  formatConfig     Json // DelFormatColumn[] — 배송 파일 컬럼 매핑\n  labelColumns     Json    @default(\"[]\") // string[] — 활성화된 DelFieldMapping 키 (max 3). 배송 파일 생성 시 이 컬럼만 옵션별 값으로 덮어씀.\n  defaultSplitMode String  @default(\"order\") // 'order' | 'option' — 배송 파일 생성 시 기본 분할 모드\n\n  space         Space                    @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  orders        DelOrder[]\n  productLabels DelShippingMethodLabel[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n}\n\n// 배송 방식 × 옵션별 필드 오버라이드 (배송 파일 생성 시 적용)\nmodel DelShippingMethodLabel {\n  id               String @id @default(cuid())\n  spaceId          String\n  shippingMethodId String\n  optionId         String\n  overrides        Json // { [field: DelFieldMapping]: string }\n\n  space          Space             @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  shippingMethod DelShippingMethod @relation(fields: [shippingMethodId], references: [id], onDelete: Cascade)\n  option         InvProductOption  @relation(fields: [optionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([shippingMethodId, optionId])\n  @@index([spaceId])\n  @@index([optionId])\n}\n\n// 배송 배치 (한 번의 배송 등록 작업 단위)\nmodel DelBatch {\n  id      String         @id @default(cuid())\n  spaceId String\n  status  DelBatchStatus @default(DRAFT)\n  source  DelBatchSource @default(MANUAL)\n  label   String?\n\n  space          Space                  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  orders         DelOrder[]\n  movements      InvMovement[] // 이력 이전(IMPORT) 시 생성된 OUTBOUND. 묶음 삭제 시 cascade.\n  stockMovements ChannelStockMovement[] // 완료(출고) 시 차감된 채널 재고 이력. 묶음 삭제 시 cascade.\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@index([spaceId])\n  @@index([spaceId, status])\n  @@index([spaceId, source])\n}\n\n// 개별 주문 (배송 등록 행 1개)\nmodel DelOrder {\n  id               String  @id @default(cuid())\n  spaceId          String\n  batchId          String\n  shippingMethodId String?\n  channelId        String? // 셀러 허브 공용 Channel FK\n\n  // PII 암호화 필드\n  recipientNameEnc String\n  recipientNameIv  String\n  phoneEnc         String\n  phoneIv          String\n  addressEnc       String\n  addressIv        String\n  postalCode       String? // 우편번호 (비PII)\n  deliveryMessage  String?\n  memo             String? // 사용자 메모\n\n  // 주문 메타\n  orderDate     DateTime\n  orderNumber   String?\n  paymentAmount Decimal? @db.Decimal(18, 2)\n\n  space          Space              @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  batch          DelBatch           @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  shippingMethod DelShippingMethod? @relation(fields: [shippingMethodId], references: [id])\n  channel        Channel?           @relation(fields: [channelId], references: [id], onDelete: SetNull)\n  items          DelOrderItem[]\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId])\n  @@index([batchId])\n  @@index([spaceId, orderDate])\n}\n\n// 주문 상품 (max 10, 앱 레벨 검증)\nmodel DelOrderItem {\n  id        String  @id @default(cuid())\n  orderId   String\n  name      String // 원본 텍스트 — 미매칭 fallback 및 감사용\n  quantity  Int\n  optionId  String? // 단일 옵션 매칭 — InvProductOption.id (listingId와 상호 배타)\n  listingId String? // 판매채널 상품(ProductListing) 매칭 — fulfillments로 실제 출고 옵션·수량 팬아웃\n\n  order        DelOrder                  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  option       InvProductOption?         @relation(fields: [optionId], references: [id], onDelete: SetNull)\n  listing      ProductListing?           @relation(fields: [listingId], references: [id], onDelete: SetNull)\n  fulfillments DelOrderItemFulfillment[]\n\n  @@index([orderId])\n  @@index([optionId])\n  @@index([listingId])\n}\n\n// 채널별 상품 별칭 사전 — 원본 상품명을 판매채널 상품(listing) 또는 단일 옵션에 매핑.\n// optionId 또는 listingId 중 하나가 필수 (CHECK 제약으로 보장).\n// 매칭 우선순위: listingId 있으면 listing, 아니면 optionId.\nmodel ChannelProductAlias {\n  id        String  @id @default(cuid())\n  spaceId   String\n  channelId String\n  aliasName String // 정규화된 원본 상품명 (normalizeAlias 출력)\n  optionId  String?\n  listingId String?\n  // multi-target 수동 매칭: fulfillments가 있으면 listingId·optionId 대신 사용\n  // (우선순위: fulfillments[] > listingId > optionId)\n\n  space        Space                            @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel      Channel                          @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  option       InvProductOption?                @relation(fields: [optionId], references: [id], onDelete: Cascade)\n  listing      ProductListing?                  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  fulfillments ChannelProductAliasFulfillment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([channelId, aliasName])\n  @@index([spaceId])\n  @@index([optionId])\n  @@index([listingId])\n}\n\n// 수동 매칭 alias의 다중 fulfillment 자식 테이블.\n// 한 raw name이 여러 (옵션, 수량)으로 팬아웃되는 경우(예: \"블랙 2 + 화이트 1\") 사용.\n// quantity 의미: \"1 주문당 perSet 수량\" — import 시점에 orderItem.quantity 곱해져 실제 출고 수량 산출.\nmodel ChannelProductAliasFulfillment {\n  id       String @id @default(cuid())\n  aliasId  String\n  optionId String\n  quantity Int\n\n  alias  ChannelProductAlias @relation(fields: [aliasId], references: [id], onDelete: Cascade)\n  option InvProductOption    @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@index([aliasId])\n  @@index([optionId])\n}\n\n// 컬럼 매핑 프리셋 (업로드 시 header name → field 매핑을 저장)\nmodel DelColumnMappingPreset {\n  id                  String  @id @default(cuid())\n  spaceId             String\n  name                String\n  mapping             Json // Array<{ headerName: string; field: string }>\n  channelId           String? // 프리셋 적용 시 배송 등록의 판매채널로 자동 입력될 채널\n  paymentIsOrderTotal Boolean @default(false) // 결제금액이 \"주문 총액\"(행마다 반복)이면 import 시 행 합산 안 함\n\n  space   Space    @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel Channel? @relation(\"PresetChannel\", fields: [channelId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n  @@index([channelId])\n}\n\n// 데이터 연동 이력\nmodel DelIntegrationHistory {\n  id          String   @id @default(cuid())\n  spaceId     String\n  type        String // \"SALES\" | \"INVENTORY\"\n  dateFrom    DateTime\n  dateTo      DateTime\n  totalOrders Int\n  movementIds String[]\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId])\n}\n\n// ─── 셀러 허브 공용 모델 ──────────────────────────────────────────────────────\n\n// 브랜드 (상품에 연결, Space 단위)\nmodel Brand {\n  id      String  @id @default(cuid())\n  spaceId String\n  name    String\n  logoUrl String?\n  memo    String?\n\n  space          Space           @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  products       InvProduct[]\n  productionRuns ProductionRun[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n}\n\n// 채널 유형 정의 (사용자 정의 가능, 시스템 시드 포함)\n// isSalesChannel=false 면 이 유형의 채널을 통한 출고가 InvMovement TRANSFER로 처리됨\nmodel ChannelTypeDef {\n  id             String   @id @default(cuid())\n  spaceId        String\n  name           String // 예: \"B2C\", \"B2B\", \"내부 이관\", \"견본 발송\"\n  isSalesChannel Boolean  @default(true)\n  isSystem       Boolean  @default(false) // 시스템 시드 — 삭제 차단\n  sortOrder      Int      @default(0)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  space    Space     @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channels Channel[]\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n}\n\n// 공용 판매 채널\n// 채널 배송비 산정 방식\nenum ChannelShippingFeeType {\n  FIXED // 정액 (원)\n  PERCENT // 판매가 대비 비율\n}\n\nmodel Channel {\n  id                      String                 @id @default(cuid())\n  spaceId                 String\n  channelTypeDefId        String? // 마이그레이션 후 NOT NULL로 강제하기 전까지 nullable\n  name                    String\n  // 외부 데이터 소스 (예: 'coupang_rocket_growth'). 재고 위치(InvStorageLocation)와 동일\n  // 패턴 — 위치·채널이 같은 외부 출처를 가리키고, 공간당 소스별 1개만 연결(1:1 페어링).\n  // null = 통합재고 채널(판매자 직접 배송, 채널 재고 차감 관리).\n  // non-null = 채널 자체 배송(연동) — 마켓 풀필먼트가 배송, 연동 데이터만 표시.\n  externalSource          String?\n  // 채널 자체 배송(연동) 채널이 가리키는 대표 채널(통합재고). null이면 대표/일반 채널.\n  // 연동 채널의 판매채널 상품 화면은 대표 채널 상품을 읽기전용으로 미러링한다.\n  representativeChannelId String?\n  isActive                Boolean                @default(true)\n  useSimulation           Boolean                @default(true) // 가격 시뮬레이션 노출/필수입력 결정\n  adminUrl                String?\n  freeShipping            Boolean                @default(false)\n  freeShippingThreshold   Decimal?               @db.Decimal(18, 2) // 무료배송 최소 주문금액\n  usesMarketingBudget     Boolean                @default(false)\n  applyAdCost             Boolean                @default(false) // 시뮬레이션 시 광고비 자동 적용\n  adCostPct               Decimal?               @db.Decimal(6, 4) // 광고비율 (0~1, null=미설정 → 시뮬 앱 기본값 폴백)\n  // 배송비 산정 방식: FIXED=정액(shippingFee 원), PERCENT=판매가 대비 비율(shippingFeePct 0~1)\n  shippingFeeType         ChannelShippingFeeType @default(FIXED)\n  shippingFee             Decimal?               @db.Decimal(18, 2)\n  shippingFeePct          Decimal?               @db.Decimal(6, 4) // 배송비율 (0~1, shippingFeeType=PERCENT일 때 사용)\n  vatIncludedInFee        Boolean                @default(false) // 판매(카테고리) 수수료율에 VAT 포함 여부\n  paymentFeeIncluded      Boolean                @default(true) // 결제 수수료 포함 여부\n  paymentFeePct           Decimal?               @db.Decimal(6, 4) // 결제 수수료율 (0~1)\n  paymentFeeVatIncluded   Boolean                @default(false) // 결제 수수료율에 VAT 포함 여부 (판매 수수료와 독립)\n  requireOrderNumber      Boolean                @default(true)\n  requirePayment          Boolean                @default(true)\n  requireProducts         Boolean                @default(true)\n  sortOrder               Int                    @default(0) // 사용자 정의 정렬 순서 (오름차순, 동률은 name asc)\n\n  space                   Space                    @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channelTypeDef          ChannelTypeDef?          @relation(fields: [channelTypeDefId], references: [id], onDelete: Restrict)\n  representativeChannel   Channel?                 @relation(\"ChannelRep\", fields: [representativeChannelId], references: [id], onDelete: SetNull)\n  fulfillmentChannels     Channel[]                @relation(\"ChannelRep\")\n  feeRates                ChannelFeeRate[]\n  invMovements            InvMovement[]\n  delOrders               DelOrder[]\n  columnMappingPresets    DelColumnMappingPreset[] @relation(\"PresetChannel\")\n  productAliases          ChannelProductAlias[]\n  productListings         ProductListing[]\n  channelProducts         ChannelProduct[]\n  pricingScenarios        PricingScenario[]\n  pricingScenarioChannels PricingScenarioChannel[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@unique([spaceId, externalSource]) // 외부 소스별 1개 채널만 (NULL 다중 허용)\n  @@index([spaceId])\n  @@index([channelTypeDefId])\n  @@index([representativeChannelId])\n}\n\n// 채널별 카테고리 수수료율\n// '기본'은 시스템 보장 카테고리 (모든 채널에 항상 1건 존재)\n// 판매(카테고리) 수수료 VAT=Channel.vatIncludedInFee, 결제 수수료 VAT=Channel.paymentFeeVatIncluded (독립)\nmodel ChannelFeeRate {\n  id           String  @id @default(cuid())\n  channelId    String\n  categoryName String\n  ratePercent  Decimal @db.Decimal(6, 3)\n\n  channel Channel @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([channelId, categoryName])\n  @@index([channelId])\n}\n\n// 생산 차수 (Production Run) — 발주 단위. 여러 상품/옵션을 묶을 수 있음.\nenum ProductionCostMode {\n  TOTAL\n  BREAKDOWN\n}\n\nenum ProductionRunStatus {\n  PLANNED // 계획중\n  ORDERED // 발주완료\n  STOCKED_IN // 입고완료 (재고 입고까지 완료)\n}\n\nenum ProductionCostCategory {\n  MATERIAL // 원자재\n  LABOR // 인건비/봉제\n  PACKAGING // 포장\n  LOGISTICS // 물류\n  OTHER // 기타\n}\n\nmodel ProductionRun {\n  id                 String              @id @default(cuid())\n  spaceId            String\n  brandId            String? // 대표 브랜드 (선택). 없으면 multi-brand\n  runNo              String // Space 단위 unique 차수 번호 (전체 범위)\n  dueAt              DateTime? // 납기일 (선택)\n  completedAt        DateTime? // 완료일 (선택, 레거시 — stockedInAt 과 동기화)\n  orderedConfirmedAt DateTime? // 발주완료 전환 시점\n  stockedInAt        DateTime? // 입고완료 전환 시점 (재고 INBOUND 반영 일자)\n  stockInLocationId  String? // 입고완료 시 선택한 보관 위치\n  status             ProductionRunStatus @default(PLANNED)\n  totalCost          Decimal?            @db.Decimal(18, 2) // 총 생산원가 (TOTAL 모드: 직접 입력값 / BREAKDOWN 모드: costs 합계 캐시)\n  costMode           ProductionCostMode  @default(TOTAL)\n  memo               String?\n\n  // 발주 계획 연계 (ReorderPlan.finalize 시 brandId별 분할 생성 가능 → 1:N)\n  reorderPlanId String?\n\n  space           Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  brand           Brand?              @relation(fields: [brandId], references: [id], onDelete: SetNull)\n  stockInLocation InvStorageLocation? @relation(\"ProductionRunStockInLocation\", fields: [stockInLocationId], references: [id], onDelete: SetNull)\n  reorderPlan     ReorderPlan?        @relation(fields: [reorderPlanId], references: [id], onDelete: SetNull)\n  items           ProductionRunItem[]\n  sets            ProductionRunSet[] // 세트 기반 차수의 세트별 라인 (옵션 items 는 분해 결과)\n  costs           ProductionRunCost[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, runNo])\n  @@index([spaceId, orderedConfirmedAt])\n  @@index([spaceId, status])\n  @@index([brandId])\n  @@index([reorderPlanId])\n}\n\nmodel ProductionRunItem {\n  id           String @id @default(cuid())\n  runId        String\n  optionId     String\n  quantity     Int // 발주 수량 (불변)\n  stockedInQty Int? // 실제 입고 수량 (옵션별 분배 합). null = 입고완료 전. 0 이상 = 실입고\n\n  run    ProductionRun    @relation(fields: [runId], references: [id], onDelete: Cascade)\n  option InvProductOption @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@unique([runId, optionId])\n  @@index([optionId])\n}\n\n// 세트 기반 생산차수의 세트별 라인 — listing(=세트) 1개의 계획·입고 세트수량.\n// 옵션별 ProductionRunItem 은 이 세트들을 ProductListingItem 으로 분해한 결과.\nmodel ProductionRunSet {\n  id              String @id @default(cuid())\n  runId           String\n  listingId       String\n  listingName     String // 표시용 스냅샷 (listing 삭제/개명 대비)\n  plannedSetQty   Int // 계획된 세트 수량\n  stockedInSetQty Int? // 실제 입고된 세트 수량 합. null = 입고완료 전.\n\n  run     ProductionRun  @relation(fields: [runId], references: [id], onDelete: Cascade)\n  listing ProductListing @relation(fields: [listingId], references: [id], onDelete: Restrict)\n\n  @@unique([runId, listingId])\n  @@index([listingId])\n}\n\nmodel ProductionRunCost {\n  id          String                 @id @default(cuid())\n  runId       String\n  itemName    String // 비용 항목 (필수)\n  description String? // 상세 내용\n  category    ProductionCostCategory @default(OTHER) // 비용 분류\n  spec        Decimal?               @db.Decimal(18, 4) // 규격 (선택)\n  quantity    Decimal                @default(1) @db.Decimal(18, 4) // 수량 (필수, 기본 1)\n  unitPrice   Decimal                @db.Decimal(18, 2) // 단가 (필수)\n  amount      Decimal                @db.Decimal(18, 2) // (spec ?? 1) × quantity × unitPrice\n  note        String?\n  sortOrder   Int                    @default(0)\n  vatIncluded Boolean                @default(true) // 입력 금액에 VAT 포함(공제가능 과세매입) 여부. Phase 2 매입세액 공제용\n\n  run ProductionRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  @@index([runId])\n}\n\n// 가격 시뮬레이션 시나리오\n// 옵션 N개를 선택하고 채널/할인/비용 변수를 조합해 순수익을 계산하는 단위.\n// 결과(netProfit, margin)는 캐시이므로 inputs 변경 시 재계산 후 갱신.\nmodel PricingScenario {\n  id                    String        @id @default(cuid())\n  spaceId               String\n  channelId             String? // 레거시 단일 채널 연결 (하위 호환 유지, 추후 제거)\n  name                  String // 시나리오 이름\n  memo                  String?\n  productIds            String[]      @default([]) // 시나리오에 포함된 상품(InvProduct.id) 목록 — 상품 단위 조회용 (다대다)\n  // 시뮬레이션 전역 옵션\n  includeVat            Boolean       @default(true) // 판매가에 VAT 포함 여부\n  vatRate               Decimal       @default(0.1) @db.Decimal(6, 4) // 부가세율\n  // 프로모션 설정\n  promotionType         PromotionType @default(NONE)\n  promotionValue        Decimal?      @db.Decimal(18, 4) // FLAT: 금액, PERCENT: 0~1 비율\n  // 반품/교환 비용 반영\n  applyReturnAdjustment Boolean       @default(false)\n  inputSnapshot         Json? // 라이브 시뮬 상태 전체 + 클라 계산 요약 스냅샷 (복원·표시용 단일 소스)\n\n  space    Space                    @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel  Channel?                 @relation(fields: [channelId], references: [id], onDelete: SetNull)\n  items    PricingScenarioItem[]\n  channels PricingScenarioChannel[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, updatedAt])\n  @@index([channelId])\n}\n\n// 시나리오 ↔ 채널 M-N 조인 테이블\nmodel PricingScenarioChannel {\n  id         String @id @default(cuid())\n  scenarioId String\n  channelId  String\n  sortOrder  Int    @default(0)\n\n  scenario PricingScenario @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  channel  Channel         @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  @@unique([scenarioId, channelId])\n  @@index([scenarioId])\n  @@index([channelId])\n}\n\n// 시나리오 안의 옵션별 entry — 옵션마다 독립적인 가격/원가/비용 변수와 결과 캐시\nmodel PricingScenarioItem {\n  id         String  @id @default(cuid())\n  scenarioId String\n  optionId   String? // nullable — 수동 입력 행(manualName 사용)은 null 허용\n\n  // 수동 입력 행 (optionId가 null일 때 사용)\n  manualName      String? // 상품명 직접 입력\n  manualBrandName String? // 브랜드명 직접 입력\n  unitsPerSet     Int     @default(1) // 세트당 단위 수량 (기본 1)\n\n  // 입력 변수 — 모두 nullable이면 시뮬레이션 시점에 옵션·채널·설정에서 자동 채움\n  costPrice        Decimal? @db.Decimal(18, 2) // 원가 (없으면 InvProductOption.costPrice → 사용자 직접)\n  salePrice        Decimal  @db.Decimal(18, 2) // 사용자 입력 판매가\n  discountRate     Decimal  @default(0) @db.Decimal(6, 4) // 0~1 (예: 0.1 = 10% 할인)\n  channelFeePct    Decimal  @default(0) @db.Decimal(6, 4) // 채널 수수료율 (0~1)\n  shippingCost     Decimal  @default(0) @db.Decimal(18, 2) // 옵션당 배송비\n  packagingCost    Decimal  @default(0) @db.Decimal(18, 2)\n  adCostPct        Decimal  @default(0) @db.Decimal(6, 4)\n  operatingCostPct Decimal  @default(0) @db.Decimal(6, 4)\n\n  // 결과 캐시 (서버에서 계산해 저장)\n  finalPrice   Decimal @default(0) @db.Decimal(18, 2) // salePrice × (1 - discountRate)\n  revenueExVat Decimal @default(0) @db.Decimal(18, 2)\n  totalCost    Decimal @default(0) @db.Decimal(18, 2) // costPrice + 모든 비용\n  netProfit    Decimal @default(0) @db.Decimal(18, 2)\n  margin       Decimal @default(0) @db.Decimal(6, 4) // netProfit / revenueExVat\n\n  sortOrder Int @default(0)\n\n  scenario PricingScenario   @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  option   InvProductOption? @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@index([scenarioId])\n  @@index([optionId])\n}\n\n// Space 단위 가격 시뮬레이션 기본값\nmodel ProductPricingSettings {\n  id                      String  @id @default(cuid())\n  spaceId                 String  @unique\n  // 기존 필드 (0~100 % 단위 유지)\n  defaultOperatingCostPct Decimal @default(0) @db.Decimal(6, 3)\n  defaultAdCostPct        Decimal @default(0) @db.Decimal(6, 3)\n  defaultPackagingCost    Decimal @default(0) @db.Decimal(18, 2)\n  // 신규 필드 (0~1 비율 단위)\n  defaultChannelFeePct    Decimal @default(0) @db.Decimal(6, 4) // 기본 채널 수수료율\n  defaultShippingCost     Decimal @default(0) @db.Decimal(18, 2) // 기본 배송비\n  defaultReturnRate       Decimal @default(0) @db.Decimal(6, 4) // 기본 반품율 (0~1)\n  defaultReturnShipping   Decimal @default(0) @db.Decimal(18, 2) // 반품 건당 배송비\n  // VAT (가격 시뮬레이터 공통 — 시나리오별 VAT 대체)\n  defaultIncludeVat       Boolean @default(true) // VAT 포함 여부\n  defaultVatRate          Decimal @default(0.1) @db.Decimal(6, 4) // VAT 율 (0~1)\n  autoApplyChannelFee     Boolean @default(false) // 채널 수수료 자동 적용\n  autoApplyAdCost         Boolean @default(false) // 광고비 자동 적용\n  autoApplyShipping       Boolean @default(false) // 배송비 자동 적용\n  // 마진 등급 임계값 — 단일 기준 (사용자가 설정 페이지에서 조정 가능)\n  platformTargetGood      Decimal @default(0.25) @db.Decimal(5, 4) // '높음' 임계\n  platformTargetFair      Decimal @default(0.15) @db.Decimal(5, 4) // '적합' 하한\n  minimumAcceptableMargin Decimal @default(0.10) @db.Decimal(5, 4) // 최소 허용 마진 (할인 한계 계산용)\n  maxCostRatio            Decimal @default(0.33) @db.Decimal(5, 4) // 적정 원가율 상한 (초과 시 KPI 경고)\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Space별 옵션 값-코드 자동 학습 사전\n// 사용자가 상품 저장 시 속성 값의 코드를 수정하면 여기에 자동 upsert되고,\n// 다음 상품 생성 시 에디터가 자동 제안한다 (Space 격리 + 시스템 사전보다 우선).\nmodel SpaceOptionCodeAlias {\n  id            String @id @default(cuid())\n  spaceId       String\n  attributeName String // \"사이즈\", \"색상\", \"재질\" ...\n  value         String // \"누드\", \"블랙\" ...\n  code          String // \"NDE\", \"BLK\" ... 사용자 커스텀 축약\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, attributeName, value])\n  @@index([spaceId])\n}\n\n// ─── 판매채널 상품 (ProductListing) ─────────────────────────────────────────────\n// 채널별로 상품을 묶음 단위(N개 옵션 × 수량)로 구성해 전용 상품명·키워드·판매가로 노출.\n// 배송 업로드 매칭의 기본 단위 — 한 listing은 여러 fulfillment(실제 출고 옵션·수량)로 펼쳐진다.\n\nmodel ProductListing {\n  id               String               @id @default(cuid())\n  spaceId          String\n  channelId        String\n  channelProductId String? // 채널상품(ChannelProduct) 귀속 — null이면 단독 listing\n  internalCode     String? // 사용자 관리용 식별자 (선택)\n  searchName       String // 상품명(검색용) — 채널 리스팅 상단 노출\n  displayName      String // 상품명(노출용) — 상세 페이지 타이틀\n  managementName   String? // 상품명(관리용) — 내부 목록 표시 (없으면 searchName fallback)\n  keywords         Json                 @default(\"[]\") // string[] — 사용자 확정 키워드\n  retailPrice      Decimal?             @db.Decimal(18, 2) // 판매가격 (소비자가는 구성품에서 자동 계산)\n  // 채널 재고 (세트 단위) — 차감형 잔량.\n  // null이면 기능 off: 채널-품절 판정·자동 차감 모두 안 함 (가용재고만으로 판정).\n  // 값이 있으면 MANUAL 배치 완료(출고) 시 DelOrderItem.quantity만큼 자동 차감.\n  // 차감만 존재 — 입고/증가 조정은 사용자가 수동으로 한다. 음수 허용(오버셀 진실 반영).\n  channelStock     Int?\n  status           ProductListingStatus @default(ACTIVE)\n  memo             String?\n\n  space             Space                  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel           Channel                @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  channelProduct    ChannelProduct?        @relation(fields: [channelProductId], references: [id], onDelete: SetNull)\n  items             ProductListingItem[]\n  aliases           ChannelProductAlias[]\n  delItems          DelOrderItem[]\n  stockMovements    ChannelStockMovement[]\n  reorderPlanSets   ReorderPlanSet[] // 세트 발주 계획에서 이 listing(=세트)을 참조\n  productionRunSets ProductionRunSet[] // 세트 생산차수에서 이 listing(=세트)을 참조\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // unique 제약 없음 — listing 식별은 옵션 구성으로 이루어지며, 이름은 표시용. 같은 cp 안에서도 동일 이름 허용.\n  @@index([spaceId, channelId])\n  @@index([status])\n  @@index([channelProductId])\n}\n\n// 판매채널 상품의 구성 옵션 (InvProductOption × 수량)\nmodel ProductListingItem {\n  id        String @id @default(cuid())\n  listingId String\n  optionId  String\n  quantity  Int // 묶음 내 수량 (세트면 2, 3 등)\n  sortOrder Int    @default(0)\n\n  listing ProductListing   @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  option  InvProductOption @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@unique([listingId, optionId])\n  @@index([optionId])\n}\n\n// 채널 재고 차감 이력(원장).\n// MANUAL 배치 완료(출고) 시 listingId 매칭된 DelOrderItem 라인마다 1 레코드 생성.\n// @@unique([batchId, orderItemId])로 멱등성 보장 — 재완료 시 중복 차감 방지 + 감사 추적.\n// 차감만 기록하며 입고/복원은 없음(배치 삭제 시 cascade로 행은 삭제되나 잔량은 유지).\nmodel ChannelStockMovement {\n  id          String   @id @default(cuid())\n  spaceId     String\n  listingId   String\n  batchId     String // 차감을 유발한 배송 묶음\n  orderItemId String // 멱등 키 구성 — 출고 라인당 1 레코드\n  quantity    Int // 차감량 = DelOrderItem.quantity (세트 단위, 양수)\n  createdAt   DateTime @default(now())\n\n  space   Space          @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  listing ProductListing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  batch   DelBatch       @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@unique([batchId, orderItemId])\n  @@index([spaceId])\n  @@index([listingId])\n  @@index([batchId])\n}\n\n// 배송 주문 아이템의 실제 출고 단위 — listing 매칭이면 1:N, 단일 옵션이면 비어있음\nmodel DelOrderItemFulfillment {\n  id          String @id @default(cuid())\n  orderItemId String\n  optionId    String\n  quantity    Int // listingItem.quantity × orderItem.quantity\n\n  orderItem DelOrderItem     @relation(fields: [orderItemId], references: [id], onDelete: Cascade)\n  option    InvProductOption @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@index([orderItemId])\n  @@index([optionId])\n}\n\n// 채널상품 — channel 단위 판매 묶음의 실체 엔티티.\n// 혼합 구성(여러 product 옵션 묶음) listing도 지원.\n// 자식 ProductListing들은 channelProductId FK로 귀속됨.\nmodel ChannelProduct {\n  id        String @id @default(cuid())\n  spaceId   String\n  channelId String\n\n  baseSearchName     String\n  baseDisplayName    String?\n  baseManagementName String?\n  baseInternalCode   String?\n  memo               String?\n  keywords           Json    @default(\"[]\") // string[]\n\n  space    Space            @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel  Channel          @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  listings ProductListing[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, channelId])\n}\n\n// ─── Sales Content Deck (정보 세팅) ───────────────────────────────────────────\n\nmodel Product {\n  id            String  @id @default(cuid())\n  spaceId       String\n  name          String\n  oneLinerPitch String? // 한 줄 가치 제안\n  customFields  Json    @default(\"[]\") // [{ key: string, value: string }]\n  isActive      Boolean @default(true)\n\n  space     Space             @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  personas  ProductPersona[]\n  ideations IdeationProduct[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// Product ↔ Persona 다대다 매핑.\nmodel ProductPersona {\n  productId String\n  personaId String\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  persona Persona @relation(fields: [personaId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@id([productId, personaId])\n  @@index([productId])\n  @@index([personaId])\n}\n\nmodel Persona {\n  id           String  @id @default(cuid())\n  spaceId      String\n  name         String\n  jobTitle     String?\n  industry     String?\n  customFields Json    @default(\"[]\") // [{ key: string, value: string }]\n  isActive     Boolean @default(true)\n\n  space     Space            @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  ideations Ideation[]\n  products  ProductPersona[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\nmodel BrandProfile {\n  id               String  @id @default(cuid())\n  spaceId          String  @unique\n  companyName      String\n  shortDescription String?\n  toneOfVoice      Json? // string[] (최대 3개)\n  customFields     Json    @default(\"[]\") // [{ key: string, value: string }]\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── Sales Content Deck (AI 어댑터) ───────────────────────────────────────────\n\nenum AiGenerationStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n  REFUNDED\n}\n\n// Space(워크스페이스) 월간 AI 이미지 크레딧 — (spaceId, yearMonth) 단위로 카운터.\n// atomic UPDATE ... WHERE imageUsed < imageQuota 로 동시성 안전하게 예약.\nmodel WorkspaceAiCredit {\n  id         String @id @default(cuid())\n  spaceId    String\n  yearMonth  String // \"YYYY-MM\"\n  imageUsed  Int    @default(0)\n  imageQuota Int    @default(50)\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, yearMonth])\n  @@index([spaceId])\n}\n\n// 이미지 생성 이력. reservationId 반환용 id.\nmodel ImageGenerationLog {\n  id             String             @id @default(cuid())\n  spaceId        String\n  userId         String?\n  provider       String // 'gemini-imagen' 등\n  model          String // 'imagen-4.0-generate-001' 등\n  prompt         String\n  negativePrompt String?\n  aspectRatio    String?\n  status         AiGenerationStatus @default(PENDING)\n  outputCount    Int                @default(0)\n  creditMonth    String? // 연결된 WorkspaceAiCredit.yearMonth — refund 판단용\n  errorCode      String?\n  errorMessage   String?\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, createdAt])\n  @@index([status])\n}\n\n// 텍스트 생성 이력. Claude Code ACP / Ollama.\nmodel TextGenerationLog {\n  id             String             @id @default(cuid())\n  spaceId        String\n  userId         String?\n  provider       String // 'claude-code-acp' | 'ollama'\n  model          String? // 모델명(Ollama) 혹은 null(ACP)\n  responseFormat String? // 'text' | 'json'\n  status         AiGenerationStatus @default(PENDING)\n  contentPreview String? // 응답 앞 500자 (감사/디버그용)\n  inputTokens    Int?\n  outputTokens   Int?\n  latencyMs      Int?\n  errorCode      String?\n  errorMessage   String?\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId, createdAt])\n  @@index([status])\n}\n\n// ─── Sales Content Deck (템플릿 · 채널) ──────────────────────────────────────\n\nenum TemplateKind {\n  BLOG\n  SOCIAL\n  CARDNEWS\n}\n\nenum SalesContentPlatform {\n  BLOG_NAVER\n  BLOG_TISTORY\n  BLOG_WORDPRESS\n  THREADS\n  X\n  LINKEDIN\n  FACEBOOK\n  INSTAGRAM\n  YOUTUBE_SHORTS\n  OTHER\n}\n\nenum SalesContentChannelKind {\n  BLOG\n  SOCIAL\n}\n\nenum PublisherMode {\n  API\n  BROWSER\n  MANUAL\n}\n\nenum CollectorMode {\n  API\n  BROWSER\n  MANUAL\n  NONE\n}\n\n// 콘텐츠 템플릿. spaceId=null + isSystem=true 인 경우 모든 공간이 공유하는 시스템 템플릿.\n// MVP-6 에서 채널별로 재설계 예정. 현재는 slug 제거된 minimal shape.\nmodel Template {\n  id       String       @id @default(cuid())\n  spaceId  String? // null = 시스템 템플릿\n  name     String\n  kind     TemplateKind\n  sections Json // kind=BLOG|SOCIAL: { sections: [...] }, kind=CARDNEWS: { slides: [...] }\n  isSystem Boolean      @default(false)\n  isActive Boolean      @default(true)\n\n  space Space? @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n  @@index([kind])\n}\n\n// 배포 채널 (블로그 · 소셜). seller-hub 의 Channel 과는 구분되는 별도 엔터티.\nmodel SalesContentChannel {\n  id            String                  @id @default(cuid())\n  spaceId       String\n  platform      SalesContentPlatform\n  kind          SalesContentChannelKind\n  name          String // 사용자 표기명\n  platformSlug  String // utm_source 용 kebab\n  publisherMode PublisherMode           @default(MANUAL)\n  collectorMode CollectorMode           @default(MANUAL)\n  isActive      Boolean                 @default(true)\n  config        Json? // 채널별 구성 (blog base URL, API endpoint 등)\n\n  space       Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  contents    Content[]\n  deployments ContentDeployment[]\n  credentials ChannelCredential[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, platformSlug])\n  @@index([spaceId])\n  @@index([platform])\n}\n\n// ─── Sales Content Deck (아이데이션) ─────────────────────────────────────────\n\nenum IdeaGeneratedBy {\n  USER\n  AI\n}\n\n// ─── Sales Content Deck (콘텐츠 제작) ────────────────────────────────────────\n\nenum ContentStatus {\n  TODO // 신규 — 토픽만 선정된 상태 (본문 없음)\n  DRAFT\n  IN_REVIEW\n  APPROVED\n  SCHEDULED\n  PUBLISHED\n  ANALYZED\n}\n\nenum ContentAssetKind {\n  IMAGE\n  LINK\n}\n\n// 콘텐츠 1건. doc(Json) 은 TipTap Doc.\n// 페르소나/상품 컨텍스트는 ideationId 로 lookup (denormalize 안 함).\nmodel Content {\n  id      String        @id @default(cuid())\n  spaceId String\n  userId  String? // 작성자\n  title   String\n  body    String? // raw markdown / textual representation\n  doc     Json // TipTap doc\n  status  ContentStatus @default(DRAFT)\n\n  // SEO\n  urlSlug         String?\n  targetKeyword   String?\n  relatedKeywords Json    @default(\"[]\") // string[] (메타 태그)\n\n  // origin\n  ideationId String? // Ideation.id (FK 미설정 — 코드 레벨 lookup)\n  ideaIndex  Int? // Ideation.ideas 의 인덱스\n\n  // deploy\n  channelId String? // 기본 배포 채널 (선택)\n\n  // misc\n  snapshotHash String? // 변경 감지용\n  publishedAt  DateTime?\n  scheduledAt  DateTime?\n\n  space       Space                @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel     SalesContentChannel? @relation(fields: [channelId], references: [id], onDelete: SetNull)\n  assets      ContentAsset[]\n  versions    ContentVersion[]\n  deployments ContentDeployment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([spaceId, createdAt])\n  @@index([channelId])\n}\n\n// ─── Sales Content Deck (배포 · UTM · 클릭) ─────────────────────────────────\n\nenum DeploymentStatus {\n  SCHEDULED\n  PUBLISHING\n  PUBLISHED\n  FAILED\n  CANCELED\n}\n\n// 한 건의 Content 를 한 채널에 배포한 기록. shortSlug 은 /c/{slug} 리다이렉터 키.\nmodel ContentDeployment {\n  id           String           @id @default(cuid())\n  spaceId      String\n  contentId    String\n  channelId    String\n  shortSlug    String           @unique\n  targetUrl    String // 최종 목적지 (상품/랜딩 페이지)\n  platformUrl  String? // 실제 게시물 URL (Unit 10 에서 채움)\n  status       DeploymentStatus @default(SCHEDULED)\n  scheduledAt  DateTime?\n  publishedAt  DateTime?\n  utmSource    String?\n  utmMedium    String?\n  utmCampaign  String?\n  utmContent   String?\n  utmTerm      String?\n  errorMessage String?\n\n  space       Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  content     Content             @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  channel     SalesContentChannel @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  clickEvents ContentClickEvent[]\n  metrics     DeploymentMetric[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([contentId])\n  @@index([channelId])\n}\n\n// /c/{slug} 리다이렉터 진입 이벤트. ip 는 SHA-256 + salt 로 익명화.\nmodel ContentClickEvent {\n  id           String  @id @default(cuid())\n  spaceId      String\n  deploymentId String\n  ipHash       String?\n  userAgent    String?\n  referrer     String?\n\n  space      Space             @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  deployment ContentDeployment @relation(fields: [deploymentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([deploymentId, createdAt])\n  @@index([spaceId, createdAt])\n}\n\n// ─── Sales Content Deck (자격증명 · 작업 큐) ────────────────────────────────\n\nenum ChannelCredentialKind {\n  COOKIE // Playwright storageState JSON\n  OAUTH // access/refresh token 쌍\n  API_KEY\n}\n\nmodel ChannelCredential {\n  id               String                @id @default(cuid())\n  spaceId          String\n  channelId        String\n  kind             ChannelCredentialKind\n  encryptedPayload String // hex 인코딩 AES-256-CBC\n  iv               String // hex iv\n  expiresAt        DateTime?\n  lastVerifiedAt   DateTime?\n  lastError        String?\n\n  space   Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel SalesContentChannel @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([channelId, kind])\n  @@index([spaceId])\n}\n\nenum SalesContentJobKind {\n  PUBLISH\n  COLLECT_METRIC\n  INSIGHT_SWEEP\n}\n\nenum SalesContentJobStatus {\n  PENDING\n  CLAIMED\n  COMPLETED\n  FAILED\n}\n\n// ─── Sales Content Deck (성과 지표) ────────────────────────────────────────\n\nenum MetricSource {\n  MANUAL\n  API\n  BROWSER\n  INTERNAL // /c/[slug] 자체 집계\n}\n\n// 배포 1건 × 일자 단위 성과 지표. Unit 11 수동 입력 + Unit 12 자동 수집 공통.\nmodel DeploymentMetric {\n  id             String       @id @default(cuid())\n  spaceId        String\n  deploymentId   String\n  date           DateTime     @db.Date\n  impressions    Int?\n  views          Int?\n  likes          Int?\n  comments       Int?\n  shares         Int?\n  externalClicks Int? // 플랫폼 자체 집계 클릭 (내부 /c/[slug] 와 구분)\n  source         MetricSource @default(MANUAL)\n\n  space      Space             @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  deployment ContentDeployment @relation(fields: [deploymentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([deploymentId, date, source])\n  @@index([spaceId, date])\n  @@index([deploymentId, date])\n}\n\n// DB-backed 작업 큐. 맥미니 워커가 주기 polling 해서 claim → 처리 → complete.\nmodel SalesContentJob {\n  id           String                @id @default(cuid())\n  spaceId      String\n  kind         SalesContentJobKind\n  status       SalesContentJobStatus @default(PENDING)\n  targetId     String? // deploymentId 등 대상 엔터티 id\n  payload      Json? // kind 별 페이로드\n  scheduledAt  DateTime              @default(now())\n  claimedAt    DateTime?\n  claimedBy    String? // 워커 instance id\n  completedAt  DateTime?\n  attempts     Int                   @default(0)\n  errorMessage String?\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, scheduledAt])\n  @@index([spaceId, status])\n  @@index([kind, status])\n}\n\n// ─── Sales Content Deck (콘텐츠 버전 히스토리) ───────────────────────────────\n\n// Content 수정 직전 상태를 스냅샷으로 보존. versionNumber 는 contentId 범위 내 1부터 증가.\nmodel ContentVersion {\n  id              String  @id @default(cuid())\n  contentId       String\n  spaceId         String\n  versionNumber   Int // content 별 1부터 증가\n  title           String\n  doc             Json // 스냅샷 시점의 TipTap Doc\n  snapshotHash    String? // 변경 감지용\n  createdByUserId String? // 이 버전을 만든 사용자 (nullable — 시스템 생성 가능)\n  note            String? // \"자동 스냅샷 (PATCH)\", \"수동 저장\", \"롤백 from v3\" 같은 메타\n\n  content Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n  space   Space   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([contentId, versionNumber])\n  @@index([contentId, createdAt])\n  @@index([spaceId, createdAt])\n}\n\n// 콘텐츠 첨부 에셋 (이미지 · 링크). 이미지 URL 은 Unit 7 Supabase Storage 결과.\nmodel ContentAsset {\n  id          String           @id @default(cuid())\n  spaceId     String\n  contentId   String\n  kind        ContentAssetKind\n  slotKey     String? // TipTap 노드 key\n  url         String\n  title       String?\n  alt         String?\n  width       Int?\n  height      Int?\n  mimeType    String?\n  storagePath String? // supabase path (이미지인 경우)\n\n  space   Space   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  content Content @relation(fields: [contentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([contentId])\n  @@index([spaceId])\n}\n\n// 한 번의 아이데이션 실행 결과.\n// 페르소나(필수) + 상품(다중 선택) + 타겟 키워드 → AI 호출 → ideas[] 결과.\n// 개별 idea 를 Content 에서 참조할 때는 (ideationId, ideaIndex) 페어를 사용.\n//\n// ideas[] 의 각 element shape:\n//   {\n//     targetKeyword: string,\n//     searchVolume: { naver?: { volume, fetchedAt }, google?: {...}, aiEstimate?: { volume, model } },\n//     title: string,\n//     outline: string,           // 또는 string[]\n//     relatedKeywords: string[], // 메타 태그\n//     urlSlug: string,           // SEO friendly slug\n//   }\nmodel Ideation {\n  id              String          @id @default(cuid())\n  spaceId         String\n  userId          String? // 실행한 사용자\n  personaId       String // 필수\n  targetKeywords  Json            @default(\"[]\") // string[]\n  ideas           Json            @default(\"[]\") // Idea[] (위 shape)\n  generatedBy     IdeaGeneratedBy\n  providerName    String?\n  providerModel   String?\n  latencyMs       Int?\n  promptTraceHash String?\n  ruleIdsSnapshot Json?\n\n  space    Space             @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  persona  Persona           @relation(fields: [personaId], references: [id], onDelete: Cascade)\n  products IdeationProduct[]\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId, createdAt])\n  @@index([personaId])\n}\n\n// Ideation ↔ Product 다대다.\nmodel IdeationProduct {\n  ideationId String\n  productId  String\n\n  ideation Ideation @relation(fields: [ideationId], references: [id], onDelete: Cascade)\n  product  Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@id([ideationId, productId])\n  @@index([ideationId])\n  @@index([productId])\n}\n\n// ─── Sales Content Deck (개선 규칙 · 셀프-임프루빙) ──────────────────────────\n\nenum RuleSource {\n  USER\n  AI\n}\n\nenum RuleStatus {\n  PROPOSED\n  ACTIVE\n  ARCHIVED\n}\n\nenum RuleScope {\n  WORKSPACE\n  PRODUCT\n  PERSONA\n  CHANNEL\n  COMBINATION\n}\n\n// 아이데이션·콘텐츠 생성 프롬프트에 주입될 개선 규칙.\n// status=ACTIVE + scope 필터 매치 시 Unit 4 `loadActiveRules` 가 선택한다.\nmodel ImprovementRule {\n  id                    String     @id @default(cuid())\n  spaceId               String\n  scope                 RuleScope\n  source                RuleSource @default(USER)\n  status                RuleStatus @default(PROPOSED)\n  title                 String\n  body                  String\n  weight                Int        @default(5)\n  targetProductId       String?\n  targetPersonaId       String?\n  targetChannelId       String?\n  evidenceDeploymentIds Json? // AI 생성 시 근거가 된 배포 id 배열\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([spaceId, scope, status])\n}\n\n// ─── 발주 예측 모델 ───────────────────────────────────────────────────────────\n\n// 발주 계획 헤더 — 한 번의 발주 예측 작업 단위\nmodel ReorderPlan {\n  id          String            @id @default(cuid())\n  spaceId     String\n  planNo      String // Space 단위 unique 계획 번호\n  status      ReorderPlanStatus @default(DRAFT)\n  windowDays  Int // 예측 분석 기간 (일)\n  createdById String\n  productId   String? // 상품 단위 계획. null = 레거시 전체-계획 또는 연동위치 세트 계획\n  // 연동 위치(예: 쿠팡 로켓그로스) 세트 기반 계획. 값이 있으면 세트 계획이며 productId 는 null.\n  // productId·locationId 동시 non-null 금지(앱 레벨 검증).\n  locationId  String?\n\n  finalizedAt       DateTime? // (레거시) 확정 전환 시점 — confirmedAt 으로 대체 중\n  confirmedAt       DateTime? // \"예측 검증 시작\" 시점 = 예측 동결점 = 신뢰도 평가 앵커\n  biasAdjustApplied Json? // 적용된 bias 보정 계수 맵 { optionId: factor }\n\n  totalSuggestedQty Int // 전체 옵션 제안 수량 합계\n  totalFinalQty     Int // 전체 옵션 최종 확정 수량 합계\n  memo              String?\n\n  // revision 계보 — 확정건 수정은 same-row 변경이 아니라 revert→새 DRAFT revision 생성\n  supersededAt       DateTime? // 이 계획이 revert되어 대체된 시점\n  supersededByPlanId String? // 대체한 새 계획 id\n  sourcePlanId       String? // 이 계획이 어느 확정 계획에서 revert되어 파생됐는지\n\n  space     Space               @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  createdBy User                @relation(fields: [createdById], references: [id], onDelete: Restrict)\n  product   InvProduct?         @relation(fields: [productId], references: [id], onDelete: SetNull)\n  location  InvStorageLocation? @relation(fields: [locationId], references: [id], onDelete: SetNull)\n\n  // self-relation: source(확정 원본) ← revisions(파생 초안)\n  sourcePlan ReorderPlan?  @relation(\"PlanRevision\", fields: [sourcePlanId], references: [id], onDelete: SetNull)\n  revisions  ReorderPlan[] @relation(\"PlanRevision\")\n\n  items          ReorderPlanItem[]\n  sets           ReorderPlanSet[] // 연동위치 세트 계획의 세트별 라인 (옵션 items 는 분해 결과)\n  accuracies     ReorderPlanAccuracy[]\n  productionRuns ProductionRun[] // \"생산차수 생성\" 액션으로 brandId별 분할 생성 가능 (1:N)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, planNo])\n  @@index([spaceId, status])\n  @@index([spaceId, productId])\n  @@index([spaceId, locationId])\n  @@index([spaceId, confirmedAt])\n  @@index([sourcePlanId])\n  @@index([createdById])\n}\n\n// 세트 기반 발주 계획의 세트별 라인 — listing(=세트) 1개의 제안·최종 세트수량.\n// 옵션별 ReorderPlanItem 은 이 세트들을 ProductListingItem 으로 분해한 결과(공유 옵션은 Σ 합산).\nmodel ReorderPlanSet {\n  id              String @id @default(cuid())\n  planId          String\n  listingId       String\n  listingName     String // 표시용 스냅샷\n  currentSetStock Int // 계획 생성 시점 세트 가용재고(파이프라인) 스냅샷\n  suggestedSetQty Int // 병목 환산 제안 세트수량\n  finalSetQty     Int // 사용자 확정 세트수량\n  sortOrder       Int    @default(0)\n\n  plan    ReorderPlan    @relation(fields: [planId], references: [id], onDelete: Cascade)\n  listing ProductListing @relation(fields: [listingId], references: [id], onDelete: Restrict)\n\n  @@unique([planId, listingId])\n  @@index([listingId])\n}\n\n// 발주 계획 옵션별 라인 — 옵션 1개의 예측 결과 및 최종 수량\nmodel ReorderPlanItem {\n  id        String @id @default(cuid())\n  planId    String\n  optionId  String\n  productId String\n\n  currentStock        Int // 현재 재고 수량\n  dailyAvgForecast    Decimal              @db.Decimal(18, 4) // 일평균 예측 소진량\n  forecastModel       ReorderForecastModel // 사용된 예측 모델\n  leadTimeDays        Int // 리드타임 (일)\n  safetyStockQty      Int // 안전재고 수량\n  suggestedQty        Int // 공식 계산 제안 수량\n  roundedSuggestedQty Int // 라운딩 적용 후 제안 수량\n  finalQty            Int // 사용자 확정 수량\n  roundUnit           Int // 라운딩 단위 (10 or 100 등)\n\n  rationale String? @db.Text // LLM 생성 근거 텍스트\n  userNote  String? @db.Text // 사용자 입력 메모\n\n  biasAdjustFactor Decimal  @db.Decimal(6, 4) // 적용된 bias 보정 계수 (1.0 = 보정 없음)\n  confidenceScore  Decimal? @db.Decimal(6, 4) // 예측 신뢰도 (0~1, null = 미산출)\n  inputsSnapshot   Json // 예측 재현 가능 입력값 스냅샷 (초안 생성 당시 입력)\n\n  // 레이어드 발주(연동 세트 + 직접 배송) 전용 — 레이어별 GROSS(현재고·안전재고 차감 전, float).\n  // 옵션 수요가 진실이므로 로켓/직접 raw GROSS를 각각 보관하고, 최종 = max(0, ceil(로켓+직접+safety−stock)).\n  // 세트는 발주 옵션의 역산 표시(파생)일 뿐 이 값으로 되먹이지 않는다(중복 세트 과다집계 방지).\n  // null = 비레이어드(일반 상품/위치 세트) 플랜.\n  rocketGrossQty Decimal? @db.Decimal(18, 4)\n  directGrossQty Decimal? @db.Decimal(18, 4)\n\n  // \"예측 검증 시작\"(확정) 시점에 동결한 예측 스냅샷 — 신뢰도 측정의 단일 진실원.\n  // null = 미확정. accuracy는 live 값이 아니라 이 동결값을 읽어야 사후 수정에 오염 안 됨.\n  confirmedDailyAvgForecast Decimal?               @db.Decimal(18, 4)\n  confirmedLeadTimeDays     Int?\n  confirmedSafetyStockQty   Int?\n  confirmedFinalQty         Int?\n  snapshotSource            ReorderSnapshotSource? // LIVE(확정 시점) | BACKFILLED(마이그 근사)\n\n  plan    ReorderPlan      @relation(fields: [planId], references: [id], onDelete: Cascade)\n  option  InvProductOption @relation(fields: [optionId], references: [id], onDelete: Restrict)\n  product InvProduct       @relation(fields: [productId], references: [id], onDelete: Restrict)\n\n  @@unique([planId, optionId])\n  @@index([planId])\n  @@index([optionId])\n}\n\n// 발주 계획 적중률 결과 — 입고 후 실제 소진 vs 예측 비교\nmodel ReorderPlanAccuracy {\n  id       String @id @default(cuid())\n  planId   String\n  optionId String\n\n  evaluatedAt DateTime // 적중률 계산 시점\n  periodStart DateTime // 평가 기간 시작 (stockedInAt)\n  periodEnd   DateTime // 평가 기간 종료 (stockedInAt + leadTimeDays)\n\n  actualOutbound   Int // 실제 출고 수량\n  forecastOutbound Decimal @db.Decimal(18, 4) // 예측 출고 수량 (dailyAvgForecast × leadTimeDays)\n\n  wape Decimal @db.Decimal(10, 4) // WAPE (Weighted Absolute Percentage Error)\n  bias Decimal @db.Decimal(10, 4) // Bias% = (forecast - actual) / actual (양수 = 과예측)\n\n  stockoutDays  Int // 재고 소진 일수 (일별 잔량 시뮬레이션)\n  overstockDays Int // 과잉재고 일수\n\n  // revert/supersede 시 삭제 대신 무효화 — 학습/제안 집계는 ACTIVE만 사용\n  validity         ReorderAccuracyValidity @default(ACTIVE)\n  evaluationStatus ReorderEvaluationStatus @default(MEASURED) // 옵션별 평가 진행 상태\n  // provenance — 이 계획 예측에 입력으로 쓰인 bias 출처(어느 정산 계획에서 학습됐는지)\n  biasSourcePlanId String?\n\n  plan   ReorderPlan      @relation(fields: [planId], references: [id], onDelete: Cascade)\n  option InvProductOption @relation(fields: [optionId], references: [id], onDelete: Restrict)\n\n  @@unique([planId, optionId])\n  @@index([planId])\n  @@index([optionId])\n  @@index([validity])\n}\n\n// ─── 재무 관리 Deck (Finance) ─────────────────────────────────────────────────\n// 현금주의(cash-basis) 모델. 은행/카드 거래내역 업로드 → 계정과목 분류 → 현금흐름·잔고·부채.\n\nenum FinAccountKind {\n  BANK\n  CARD\n}\n\nenum FinCategoryType {\n  ASSET\n  LIABILITY\n  EQUITY\n  INCOME\n  EXPENSE\n  TRANSFER\n}\n\n// 손익 흐름도(현금흐름 상세 Sankey) 역할 — level-1 대분류에만 부여.\n// 미태그 수입=기타수익, 미태그 지출=판매관리비(OPEX)로 취급.\nenum FinFlowRole {\n  MERCH_SALES // 상품매출 (매출총이익 = 상품매출 − 매출원가)\n  COGS // 매출원가\n  OPEX // 영업비용(판매관리비)\n  FINANCING_COST // 금융비용\n}\n\nenum FinClassRuleMatchType {\n  EXACT // 정정 학습 — 정규화된 적요/가맹점 완전 일치 (고신뢰 = 자동분류)\n  KEYWORD // 시드/부분 키워드 포함 매칭 (저신뢰 = 검토 제안)\n}\n\nenum FinClassRuleSource {\n  USER // 사용자 분류로 학습\n  SEED // K-IFRS 시드 키워드\n}\n\nenum FinImportStatus {\n  DRAFT\n  COMMITTED\n}\n\nenum FinTxnDirection {\n  IN // 수입\n  OUT // 지출\n}\n\nenum FinClassStatus {\n  CLASSIFIED\n  REVIEW\n  UNCLASSIFIED\n}\n\nenum FinStagedResolution {\n  NEW\n  DUP_SAME // identity 일치 + content 동일 → 건너뜀\n  DUP_CHANGED // identity 일치 + content 상이 → 자동 content 반영(분류는 기존 사용자 분류 보존)\n  DUP_OVERWRITE // 사용자가 \"유지\" 명시 선택 → 확정 시 계정과목/분류까지 덮어쓰기\n}\n\nenum FinSnapshotSource {\n  DERIVED // 거래후잔액에서 파생\n  MANUAL // 사용자 입력\n}\n\n// 금융 계좌 (은행 계좌 / 카드). 파일 업로드 시 preamble에서 자동 감지 후 사용자 확인.\nmodel FinAccount {\n  id                 String         @id @default(cuid())\n  spaceId            String\n  name               String\n  holder             String? // 실제 계좌 예금주명\n  kind               FinAccountKind\n  institution        String // 은행·카드사명\n  accountNumber      String? // 마스킹 가능\n  accountType        String? // 입출금/보통예금/법인카드 등\n  openingBalance     Decimal?       @db.Decimal(18, 2)\n  // 기준(현재) 잔액 — 표시용. 은행 거래 확정 시 마지막 일자 거래후잔액으로 자동 갱신(기준일 이후일 때만).\n  // 대시보드 잔액 계산(월별 스냅샷)에는 관여하지 않는다.\n  currentBalance     Decimal?       @db.Decimal(18, 2)\n  currentBalanceAsOf DateTime?\n\n  space            Space                @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  imports          FinImport[]\n  transactions     FinTransaction[]\n  stagedRows       FinStagedRow[]\n  balanceSnapshots FinBalanceSnapshot[]\n  mappingPresets   FinMappingPreset[]\n  liabilities      FinLiability[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, accountNumber])\n  @@index([spaceId])\n}\n\n// 부채 (대출 등) — 수기 관리. 대시보드 인라인 Dialog로 잔액 등록/갱신.\nmodel FinLiability {\n  id             String    @id @default(cuid())\n  spaceId        String\n  name           String\n  lender         String?\n  principal      Decimal   @db.Decimal(18, 2)\n  balance        Decimal   @db.Decimal(18, 2)\n  rate           String? // \"연 4.8%\" 등 표시 문자열\n  dueDate        String? // \"2027-03\" 등\n  monthlyPayment Decimal?  @db.Decimal(18, 2)\n  memo           String?\n  accountId      String? // 대출 계좌로 지정한 FinAccount (선택)\n  // 이 시점까지의 연결 상환 거래는 balance 에 이미 반영됨(워터마크). 이후 상환은 \"감지\" 대상.\n  balanceAsOf    DateTime?\n\n  space      Space            @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  account    FinAccount?      @relation(fields: [accountId], references: [id], onDelete: SetNull)\n  repayments FinTransaction[] // 이 부채에 귀속된 상환 거래\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n  @@index([accountId])\n}\n\n// 계정과목 트리 (표준 K-IFRS 시드 + 사용자 하위계정). 분류 타깃 = leaf.\nmodel FinCategory {\n  id         String          @id @default(cuid())\n  spaceId    String\n  parentId   String?\n  name       String\n  code       String? // K-IFRS 코드\n  alias      String?\n  type       FinCategoryType\n  groupLabel String? // 변동비/고정비/마케팅비 등 사용자 그룹\n  flowRole   FinFlowRole? // 손익 흐름도 역할 (대분류에만 부여)\n  isSystem   Boolean         @default(false)\n  isActive   Boolean         @default(true)\n  sortOrder  Int             @default(0)\n\n  space    Space         @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  parent   FinCategory?  @relation(\"FinCategoryTree\", fields: [parentId], references: [id], onDelete: Cascade)\n  children FinCategory[] @relation(\"FinCategoryTree\")\n\n  classRules   FinClassRule[]\n  transactions FinTransaction[]\n  stagedRows   FinStagedRow[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, parentId, name])\n  @@index([spaceId])\n  @@index([parentId])\n}\n\n// 적요/가맹점 → 계정과목 학습 규칙 (ChannelProductAlias 패턴).\nmodel FinClassRule {\n  id          String                @id @default(cuid())\n  spaceId     String\n  matchKey    String // 정규화된 적요/가맹점 or 키워드\n  matchType   FinClassRuleMatchType @default(EXACT)\n  categoryId  String\n  // 방향별 규칙 구분 — 동일 적요라도 비용(OUT)/수입(IN)을 별개 규칙으로 분류.\n  // null = 방향 무관(이체 시드 등). 사용자 EXACT 규칙은 행의 방향(IN/OUT)을 가진다.\n  direction   FinTxnDirection?\n  learnedFrom FinClassRuleSource    @default(USER)\n  memo        String? // 규칙 학습 시 함께 저장한 메모 — 자동분류 시 스테이징 행 memo로 복사\n\n  space    Space       @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  category FinCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, matchKey, direction])\n  @@index([spaceId])\n  @@index([categoryId])\n}\n\n// 소스별 컬럼 매핑 프리셋 (헤더 → 필드 기억, DelColumnMappingPreset 패턴).\nmodel FinMappingPreset {\n  id               String         @id @default(cuid())\n  spaceId          String\n  name             String\n  institution      String\n  kind             FinAccountKind\n  mapping          Json // Array<{ headerName, field }>\n  defaultAccountId String?\n  dateFormat       String?\n\n  space          Space       @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  defaultAccount FinAccount? @relation(fields: [defaultAccountId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, name])\n  @@index([spaceId])\n}\n\n// 업로드 배치 / 스테이징 헤더 (파일 1개 = import 1개).\nmodel FinImport {\n  id            String          @id @default(cuid())\n  spaceId       String\n  accountId     String\n  fileName      String\n  institution   String\n  kind          FinAccountKind\n  status        FinImportStatus @default(DRAFT)\n  periodFrom    DateTime?\n  periodTo      DateTime?\n  totalRows     Int             @default(0)\n  committedRows Int             @default(0)\n\n  space        Space            @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  account      FinAccount       @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  stagedRows   FinStagedRow[]\n  transactions FinTransaction[]\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId])\n  @@index([accountId])\n}\n\n// 확정 전 검토 행 (commit 시 FinTransaction 으로 승격, dedup 적용).\nmodel FinStagedRow {\n  id            String              @id @default(cuid())\n  importId      String\n  spaceId       String\n  accountId     String\n  raw           Json\n  txnDate       DateTime\n  direction     FinTxnDirection\n  amount        Decimal             @db.Decimal(18, 2)\n  balanceAfter  Decimal?            @db.Decimal(18, 2)\n  description   String?\n  counterparty  String?\n  approvalNo    String?\n  cancelFlag    String?\n  memo          String? // 사용자 메모 — 저장 처리 시 확정 거래로 이관\n  categoryId    String?\n  classStatus   FinClassStatus      @default(UNCLASSIFIED)\n  matchedRuleId String? // soft ref — 규칙 재학습/삭제 가능\n  identityKey   String\n  contentHash   String\n  resolution    FinStagedResolution @default(NEW)\n\n  import   FinImport    @relation(fields: [importId], references: [id], onDelete: Cascade)\n  space    Space        @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  account  FinAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  category FinCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([importId])\n  @@index([spaceId])\n}\n\n// 확정 거래 (장부). identityKey unique 로 중복 불가.\nmodel FinTransaction {\n  id            String          @id @default(cuid())\n  spaceId       String\n  accountId     String\n  importId      String?\n  txnDate       DateTime\n  direction     FinTxnDirection\n  amount        Decimal         @db.Decimal(18, 2)\n  balanceAfter  Decimal?        @db.Decimal(18, 2)\n  description   String?\n  counterparty  String?\n  memo          String?\n  categoryId    String?\n  liabilityId   String? // 상환으로 귀속된 부채 (선택)\n  isTransfer    Boolean         @default(false)\n  classStatus   FinClassStatus  @default(UNCLASSIFIED)\n  matchedRuleId String? // soft ref\n  approvalNo    String?\n  cancelFlag    String?\n  identityKey   String // 안정 키 — BANK: account+date+dir+amount, CARD: 승인번호+이용일+취소구분\n  contentHash   String // 가변 필드 해시 — 변경 감지용\n\n  space     Space         @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  account   FinAccount    @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  import    FinImport?    @relation(fields: [importId], references: [id], onDelete: SetNull)\n  category  FinCategory?  @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  liability FinLiability? @relation(fields: [liabilityId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, accountId, identityKey])\n  @@index([spaceId, txnDate])\n  @@index([spaceId, categoryId])\n  @@index([liabilityId])\n}\n\n// 계좌 × 월말 잔고 스냅샷 (대시보드 sparkline·재무상태). 거래 없는 달은 직전 스냅샷 이월.\nmodel FinBalanceSnapshot {\n  id        String            @id @default(cuid())\n  spaceId   String\n  accountId String\n  yearMonth String // \"YYYY-MM\"\n  balance   Decimal           @db.Decimal(18, 2)\n  source    FinSnapshotSource @default(DERIVED)\n\n  space   Space      @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  account FinAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, accountId, yearMonth])\n  @@index([spaceId])\n  @@index([accountId])\n}\n\n// ════════════════════════════════════════════════════════════════════════════\n// 채용 관리 Deck (Hiring) — 공고 제작(hiring-posts) + 지원자 관리(hiring-applicants)\n// 두 deck이 이 스키마를 공유한다. PII는 DelOrder 선례(*Enc + *Iv, AES-256-CBC)\n// + 매칭용 HMAC-SHA256 해시(*Hash, 키: HIRING_HMAC_KEY) 컬럼을 병행한다.\n// 암복호화/해시는 src/lib/hiring/pii.ts 의 write-path 유틸에서만 수행 (Prisma 훅 없음).\n// ════════════════════════════════════════════════════════════════════════════\n\nenum HiringPostingStatus {\n  DRAFT // 작성 중 (임시저장)\n  ACTIVE // 발행됨 — 공개 URL 라이브\n  CLOSED // 마감\n  ARCHIVED // 보관 (목록 기본 제외)\n}\n\nenum HiringJobType {\n  FULL_TIME\n  PART_TIME\n  CONTRACT\n  FREELANCER\n  INTERN\n}\n\nenum HiringPayFrequency {\n  HOURLY\n  DAILY\n  WEEKLY\n  MONTHLY\n  YEARLY\n  PER_TASK\n  TBD\n}\n\n// 지원 상태머신 1축: 최종 결과\nenum HiringApplicationStage {\n  HIRING // 진행 중\n  ACCEPTED // 합격\n  REJECTED // 불합격\n}\n\n// 지원 상태머신 2축: 채용 단계\nenum HiringProcessStage {\n  APPLIED // 서류 접수\n  INTERVIEW // 면접\n  JOB_OFFER // 처우 협의/최종 제안\n}\n\nenum HiringContentSourceType {\n  POSTING_DETAIL // 공고 상세 블록\n  DETAIL_TEMPLATE // 재사용 템플릿 블록\n}\n\nenum HiringNotificationType {\n  INTERVIEW\n  JOB_OFFER\n  ACCEPTED\n  REJECTED\n}\n\n// 매장/지점 (opening Store — 테넌트 아님, Space 하위 기준정보)\nmodel HiringStore {\n  id            String  @id @default(cuid())\n  spaceId       String\n  name          String\n  roadAddress   String? // 도로명 주소\n  detailAddress String? // 상세 주소\n  zipcode       String?\n  isActive      Boolean @default(true)\n\n  space             Space                    @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  postingStores     HiringPostingStore[]\n  applicationStores HiringApplicationStore[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// 직무 (opening Position — category는 문자열 스냅샷으로 단순화, 별도 taxonomy 테이블 없음)\nmodel HiringPosition {\n  id       String  @id @default(cuid())\n  spaceId  String\n  name     String\n  category String? // 직군 분류 (자유 문자열)\n  isActive Boolean @default(true)\n\n  space            Space                   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  postingPositions HiringPostingPosition[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// 채용 공고 (opening Posting)\nmodel HiringPosting {\n  id      String              @id @default(cuid())\n  spaceId String\n  uuid    String              @unique @default(uuid()) // 공개 URL 키 (/p/{uuid})\n  title   String\n  status  HiringPostingStatus @default(DRAFT)\n\n  // 상세 본문: 섹션 블록 JSON (posting_title/company_intro/positions/stores/manager/content/image …)\n  detail Json?\n\n  // ⚠️ 이름 주의: HiringPosting.applicationEntries = 지원서 \"폼 스키마\" 정의,\n  //    HiringApplication.applicationEntries = 지원자가 제출한 \"값\". (opening 유래 동명이의)\n  applicationEntries Json?\n\n  // 담당자 연락처 (PII — 지원자 알림 발신 표기용)\n  managerNameEnc  String?\n  managerNameIv   String?\n  managerPhoneEnc String?\n  managerPhoneIv  String?\n\n  closingDate         DateTime? // 마감일 (지나면 CLOSED 처리 — 후속 cron)\n  publishedAt         DateTime?\n  notificationEnabled Boolean   @default(true)\n  authorUserId        String? // 작성자 (Supabase user id — 관계 미연결 스냅샷)\n  appliedTemplateName String? // 마지막 저장/적용 상세 템플릿 이름 스냅샷 (표시용)\n  appliedTemplateId   String? // 마지막 저장/적용 템플릿 id (덮어쓰기 대상 — FK 미연결 스냅샷)\n  appliedTemplateAt   DateTime? // 마지막 저장/적용 시각 (표시용)\n\n  space        Space                   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  positions    HiringPostingPosition[]\n  stores       HiringPostingStore[]\n  managers     HiringPostingManager[]\n  contents     HiringContent[]\n  applications HiringApplication[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([spaceId, createdAt])\n}\n\n// 공고 × 직무 상세 (근무조건 스냅샷 — opening PostingPosition)\nmodel HiringPostingPosition {\n  id         String  @id @default(cuid())\n  spaceId    String\n  postingId  String\n  positionId String?\n  name       String // 직무명 스냅샷\n\n  jobType      HiringJobType?\n  payFrequency HiringPayFrequency?\n  payAmount    Int? // 급여 (원)\n  workDays     Json? // 근무 요일 int[] (0=일 … 6=토)\n  workStartAt  String? // \"HH:mm\"\n  workEndAt    String? // \"HH:mm\"\n  headcount    Int? // 모집 인원\n  experience   String? // 경력 요건 (자유 문자열)\n  education    String? // 학력 요건\n\n  jobDescription          String? // 담당 업무\n  requiredQualifications  String?\n  preferredQualifications String?\n\n  posting      HiringPosting       @relation(fields: [postingId], references: [id], onDelete: Cascade)\n  position     HiringPosition?     @relation(fields: [positionId], references: [id], onDelete: SetNull)\n  applications HiringApplication[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  space     Space    @relation(fields: [spaceId], references: [id])\n\n  @@index([postingId])\n  @@index([spaceId])\n}\n\n// 공고 × 매장 조인\nmodel HiringPostingStore {\n  id        String @id @default(cuid())\n  postingId String\n  storeId   String\n\n  posting HiringPosting @relation(fields: [postingId], references: [id], onDelete: Cascade)\n  store   HiringStore   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([postingId, storeId])\n}\n\n// 공고 × 알림 담당자 (workdeck User id — SpaceMember 전제)\nmodel HiringPostingManager {\n  id        String @id @default(cuid())\n  postingId String\n  userId    String\n\n  posting HiringPosting @relation(fields: [postingId], references: [id], onDelete: Cascade)\n\n  @@unique([postingId, userId])\n}\n\n// 공고 상세 리치 블록 (Excalidraw 캔버스 — data JSON + export 이미지 storage 키)\nmodel HiringContent {\n  id          String                  @id @default(cuid())\n  spaceId     String? // null = 글로벌 샘플 템플릿 소속 블록\n  sourceType  HiringContentSourceType\n  postingId   String? // sourceType=POSTING_DETAIL 일 때\n  templateId  String? // sourceType=DETAIL_TEMPLATE 일 때\n  contentType String                  @default(\"excalidraw\")\n  title       String? // 블록 리스트에 표시할 사용자 지정 제목 (null이면 \"카드 N\")\n  data        Json? // excalidraw scene JSON\n  imagePath   String? // hiring-assets 버킷 내 export PNG 경로\n  sortOrder   Int                     @default(0)\n\n  space    Space?                @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  posting  HiringPosting?        @relation(fields: [postingId], references: [id], onDelete: Cascade)\n  template HiringDetailTemplate? @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([postingId])\n  @@index([templateId])\n  @@index([spaceId])\n}\n\n// 재사용 상세 템플릿\nmodel HiringDetailTemplate {\n  id        String  @id @default(cuid())\n  spaceId   String? // null = 글로벌 샘플 (전 워크스페이스 읽기전용 공유)\n  name      String\n  data      Json? // 섹션 블록 JSON\n  imagePath String? // 대표 이미지 storage 경로\n  isSample  Boolean @default(false) // 글로벌 샘플 — 편집/삭제 불가, 적용만 가능\n  sourceRef String? @unique // 이관 출처 키 (opening detail_template id) — 재실행 멱등성용\n\n  space    Space?          @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  contents HiringContent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// 지원서 (opening Application — 지원자는 비인증 익명 레코드)\nmodel HiringApplication {\n  id                String  @id @default(cuid())\n  spaceId           String\n  postingId         String\n  postingPositionId String?\n  uuid              String  @unique @default(uuid()) // 내부/공개 참조 키\n\n  // 제출값 JSON — 표준 PII 항목(name/phone/email/address)은 값 제거 후 아래 enc 컬럼으로 이동,\n  // 커스텀 항목만 값 유지. (src/lib/hiring/pii.ts 참조)\n  applicationEntries Json?\n\n  // PII (AES enc + iv, 매칭 필요한 것만 HMAC hash)\n  nameEnc             String?\n  nameIv              String?\n  nameHash            String?\n  maskedName          String? // 목록 표시용 마스킹 이름 (홍*동)\n  phoneEnc            String?\n  phoneIv             String?\n  phoneHash           String? // 중복판정·블랙리스트 매칭 키\n  phoneLastDigitsHash String? // 뒷 4자리 검색\n  emailEnc            String?\n  emailIv             String?\n  emailHash           String?\n  addressEnc          String?\n  addressIv           String?\n\n  stage       HiringApplicationStage @default(HIRING)\n  hiringStage HiringProcessStage     @default(APPLIED)\n\n  referrer           String? // 유입 잡보드 (jobkorea/saramin/albamon/wanted …)\n  directRegistration Boolean @default(false) // 고용주 직접 등록\n  duplicated         Boolean @default(false) // phoneHash 중복 감지\n  memo               String?\n\n  privacyAgreedAt DateTime?\n  canceledAt      DateTime?\n  deletedAt       DateTime? // 소프트 삭제\n\n  space           Space                           @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  posting         HiringPosting                   @relation(fields: [postingId], references: [id], onDelete: Cascade)\n  postingPosition HiringPostingPosition?          @relation(fields: [postingPositionId], references: [id], onDelete: SetNull)\n  stores          HiringApplicationStore[]\n  files           HiringApplicationFile[]\n  comments        HiringComment[]\n  notifications   HiringApplicationNotification[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, stage])\n  @@index([spaceId, createdAt])\n  @@index([postingId])\n  @@index([spaceId, phoneHash])\n}\n\n// 지원 × 매장 조인 (지원자가 선택한 근무 희망 매장)\nmodel HiringApplicationStore {\n  id            String @id @default(cuid())\n  applicationId String\n  storeId       String\n\n  application HiringApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n  store       HiringStore       @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([applicationId, storeId])\n}\n\n// 지원자 첨부 파일 (이력서 등 — hiring-files 비공개 버킷, 서명 URL 접근만)\nmodel HiringApplicationFile {\n  id            String @id @default(cuid())\n  spaceId       String\n  applicationId String\n  fileName      String // 원본 파일명\n  filePath      String // 비공개 버킷 내 경로\n  mimeType      String\n  sizeBytes     Int\n\n  application HiringApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([applicationId])\n  @@index([spaceId])\n}\n\n// 지원서 내부 메모 (고용주 팀 코멘트)\nmodel HiringComment {\n  id            String    @id @default(cuid())\n  spaceId       String\n  applicationId String\n  userId        String // 작성자 (Supabase user id)\n  content       String\n  editedAt      DateTime?\n  deletedAt     DateTime?\n\n  application HiringApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([applicationId])\n}\n\n// 지원자 상태 알림 (uuid + tokenHash 로 30일 공개 열람)\nmodel HiringApplicationNotification {\n  id            String                 @id @default(cuid())\n  spaceId       String\n  applicationId String\n  senderUserId  String? // 발송한 담당자\n  notiType      HiringNotificationType\n  detailMessage String?\n  uuid          String                 @unique\n  tokenHash     String // 원문 토큰은 저장하지 않음 — HMAC 해시만 (상수시간 비교)\n  tokenExpireAt DateTime\n  sentAt        DateTime?\n\n  application HiringApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([applicationId])\n}\n\n// 블랙리스트 (phoneHash 매칭)\nmodel HiringBlacklist {\n  id        String  @id @default(cuid())\n  spaceId   String\n  phoneEnc  String\n  phoneIv   String\n  phoneHash String\n  reason    String?\n  isActive  Boolean @default(true)\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, phoneHash])\n}\n\n// 지원자 알림 메시지 템플릿\nmodel HiringMessageTemplate {\n  id         String    @id @default(cuid())\n  spaceId    String\n  title      String\n  content    String\n  lastUsedAt DateTime?\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// ─── 블로그 운영 Deck (Blog Ops) ──────────────────────────────────────────────\n\nenum BoCrawlStatus {\n  NONE\n  PENDING\n  DONE\n  FAILED\n}\n\nenum BoMaterialStatus {\n  PROPOSED\n  APPROVED\n  REJECTED\n  ARCHIVED\n}\n\n// 블로그 소재 발굴 대상 제품. 홈페이지 크롤 결과·AI 소구점 분석의 기준점.\nmodel BoProduct {\n  id             String        @id @default(cuid())\n  spaceId        String\n  name           String\n  category       String? // B2B / B2C\n  oneLinerPitch  String?\n  homepageUrl    String?\n  crawledText    String?\n  crawledAt      DateTime?\n  crawlStatus    BoCrawlStatus @default(NONE)\n  targetCustomer String?\n  features       Json          @default(\"[]\") // [{ name: string, description: string }]\n  ctaUrl         String?\n  customFields   Json          @default(\"[]\") // [{ key: string, value: string }]\n  isActive       Boolean       @default(true)\n\n  space     Space        @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  ideations BoIdeation[]\n  materials BoMaterial[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId])\n}\n\n// AI 소구점 발굴 실행 단위. 한 번의 생성 호출 결과를 appealPoints Json으로 보관.\nmodel BoIdeation {\n  id              String  @id @default(cuid())\n  spaceId         String\n  userId          String?\n  productId       String\n  userPromptInput String?\n  appealPoints    Json    @default(\"[]\") // [{ point, evidence, targetPain, priority }]\n  providerName    String?\n  providerModel   String?\n  latencyMs       Int?\n  promptTraceHash String?\n\n  space     Space        @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  product   BoProduct    @relation(fields: [productId], references: [id], onDelete: Cascade)\n  materials BoMaterial[]\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId, createdAt])\n  @@index([productId])\n}\n\n// 블로그 포스팅 소재. 소구점 하나를 특정 앵글로 풀어낸 글 골격.\nmodel BoMaterial {\n  id               String           @id @default(cuid())\n  spaceId          String\n  productId        String\n  ideationId       String?\n  title            String\n  appealPoint      String\n  angle            String\n  outline          Json             @default(\"[]\") // [{ section: string, description: string }]\n  targetKeyword    String?\n  status           BoMaterialStatus @default(PROPOSED)\n  approvedByUserId String?\n  approvedAt       DateTime?\n\n  space    Space       @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  product  BoProduct   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  ideation BoIdeation? @relation(fields: [ideationId], references: [id], onDelete: SetNull)\n  posts    BoPost[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([productId])\n}\n\nenum BoPostStatus {\n  GENERATING\n  DRAFT\n  IN_REVIEW\n  PUBLISH_APPROVED\n  PUBLISHED\n  FAILED\n  ARCHIVED\n}\n\nenum BoPlatform {\n  NAVER_BLOG\n  TISTORY\n  OWN_HOMEPAGE\n}\n\nenum BoPublisherMode {\n  MANUAL\n  BROWSER\n}\n\nenum BoVariantStatus {\n  GENERATING\n  READY\n  EDITED\n  FAILED\n}\n\nenum BoDeploymentStatus {\n  PENDING\n  PUBLISHING\n  PUBLISHED\n  FAILED\n  CANCELED\n  EXPORTED\n  DELETING\n  DELETED\n}\n\n// 블로그 포스트. 소재(BoMaterial)를 기반으로 AI가 생성한 실제 글 본문.\nmodel BoPost {\n  id                      String       @id @default(cuid())\n  spaceId                 String\n  userId                  String?\n  materialId              String\n  title                   String\n  doc                     Json // TipTap master doc\n  bodyMarkdown            String?\n  status                  BoPostStatus @default(GENERATING)\n  targetKeyword           String?\n  relatedKeywords         Json         @default(\"[]\")\n  ctaUrl                  String?\n  publishApprovedByUserId String?\n  publishApprovedAt       DateTime?\n  generationTraceHash     String?\n  errorMessage            String?\n\n  space       Space           @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  material    BoMaterial      @relation(fields: [materialId], references: [id], onDelete: Cascade)\n  versions    BoPostVersion[]\n  variants    BoPostVariant[]\n  deployments BoDeployment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([materialId])\n}\n\n// 포스트 버전 이력. 수동 저장·AI 재생성 시마다 스냅샷 누적.\nmodel BoPostVersion {\n  id              String  @id @default(cuid())\n  postId          String\n  spaceId         String\n  versionNumber   Int\n  title           String\n  doc             Json\n  note            String?\n  createdByUserId String?\n\n  post  BoPost @relation(fields: [postId], references: [id], onDelete: Cascade)\n  space Space  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([postId, versionNumber])\n  @@index([spaceId, createdAt])\n}\n\n// 블로그 배포 채널. 플랫폼(네이버·티스토리·자사 홈페이지)별 설정을 보관한다.\nmodel BoChannel {\n  id            String          @id @default(cuid())\n  spaceId       String\n  platform      BoPlatform\n  name          String\n  formatProfile Json            @default(\"{}\")\n  publisherMode BoPublisherMode @default(MANUAL)\n  config        Json?\n  isActive      Boolean         @default(true)\n\n  space       Space                 @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  variants    BoPostVariant[]\n  deployments BoDeployment[]\n  credentials BoChannelCredential[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([spaceId, platform, name])\n  @@index([spaceId])\n}\n\n// 포스트 × 채널별 변형. 채널 포맷에 맞춰 변환된 제목·본문·내보내기 결과를 보관한다.\nmodel BoPostVariant {\n  id               String          @id @default(cuid())\n  spaceId          String\n  postId           String\n  channelId        String\n  title            String\n  doc              Json\n  exportedMarkdown String?\n  exportedHtml     String?\n  status           BoVariantStatus @default(GENERATING)\n  errorMessage     String?\n\n  space       Space          @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  post        BoPost         @relation(fields: [postId], references: [id], onDelete: Cascade)\n  channel     BoChannel      @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  deployments BoDeployment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([postId, channelId])\n  @@index([spaceId])\n}\n\n// 포스트 배포 이력. 변형 1건을 채널에 게시한 실행 단위.\nmodel BoDeployment {\n  id           String             @id @default(cuid())\n  spaceId      String\n  postId       String\n  variantId    String\n  channelId    String\n  status       BoDeploymentStatus @default(PENDING)\n  platformUrl  String?\n  errorCode    String?\n  errorMessage String?\n  publishedAt  DateTime?\n  scheduledAt  DateTime? // 예약 발행 시각 (null = 즉시 발행)\n  deletedAt    DateTime? // 플랫폼에서 글 삭제 완료 시각\n\n  space   Space         @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  post    BoPost        @relation(fields: [postId], references: [id], onDelete: Cascade)\n  variant BoPostVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  channel BoChannel     @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, status])\n  @@index([postId])\n}\n\n// ─── Blog Ops Deck (자격증명 · 작업 큐) ──────────────────────────────────────\n\nenum BoJobKind {\n  CRAWL_HOMEPAGE\n  GENERATE_DRAFT\n  GENERATE_VARIANT\n  PUBLISH\n  DELETE_POST\n}\n\nenum BoJobStatus {\n  PENDING\n  CLAIMED\n  COMPLETED\n  FAILED\n}\n\nenum BoCredentialKind {\n  COOKIE\n  OAUTH\n  API_KEY\n}\n\n// DB-backed 작업 큐. 워커가 주기 polling 해서 claim → 처리 → complete.\nmodel BoJob {\n  id           String      @id @default(cuid())\n  spaceId      String\n  kind         BoJobKind\n  status       BoJobStatus @default(PENDING)\n  targetId     String? // variantId · deploymentId 등 대상 엔터티 id\n  payload      Json? // kind 별 페이로드\n  scheduledAt  DateTime    @default(now())\n  claimedAt    DateTime?\n  claimedBy    String? // 워커 instance id\n  completedAt  DateTime?\n  attempts     Int         @default(0)\n  errorMessage String?\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, scheduledAt])\n  @@index([spaceId, status])\n  @@index([kind, status])\n}\n\n// 채널별 자격증명. AES-256-CBC 암호화 페이로드 보관 (sc/credentials.ts 와 동일 구조).\nmodel BoChannelCredential {\n  id               String           @id @default(cuid())\n  spaceId          String\n  channelId        String\n  kind             BoCredentialKind\n  encryptedPayload String // hex 인코딩 AES-256-CBC\n  iv               String // hex iv\n  expiresAt        DateTime?\n  lastVerifiedAt   DateTime?\n  lastError        String?\n\n  space   Space     @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  channel BoChannel @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([channelId, kind])\n  @@index([channelId])\n  @@index([spaceId])\n}\n\n// ═══════════════════════════════════════════\n// 구독·결제 (Billing) — deck별 개별 구독 모델\n// ═══════════════════════════════════════════\n\n// deck별 과금 모드. FREE_BETA 기간엔 전원 무료, SUBSCRIPTION 전환 시 구독 필요.\nenum DeckPricingMode {\n  FREE_BETA\n  SUBSCRIPTION\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELED\n  EXPIRED\n}\n\nenum SubscriptionItemType {\n  DECK\n  ADDON\n}\n\nenum SubscriptionItemStatus {\n  ACTIVE\n  CANCEL_AT_PERIOD_END\n  ENDED\n}\n\nenum BillingChargeStatus {\n  PENDING\n  PAID\n  FAILED\n  CANCELED\n  REFUNDED\n}\n\n// deck 과금 정의 — 운영자가 데이터로 관리 (코드 하드코딩 금지)\nmodel BillingDeckProduct {\n  id              String          @id // DeckApp.id와 동일 키\n  name            String\n  pricingMode     DeckPricingMode @default(FREE_BETA)\n  monthlyPrice    Int // 공급가 KRW (FREE_BETA 중에도 예정가 보관)\n  paidActivatedAt DateTime? // 유료 전환 시각 — 기존 사용 Space 유예(14일) 판정 기준\n  isActive        Boolean         @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Space당 구독 1개. 단일 결제일에 아이템 합산 청구.\nmodel SpaceSubscription {\n  id               String             @id @default(cuid())\n  spaceId          String             @unique\n  status           SubscriptionStatus @default(TRIALING)\n  trialEndsAt      DateTime? // 존재 = Trial 이력 (평생 1회 판정)\n  currentPeriodEnd DateTime? // 다음 결제일\n  retryCount       Int                @default(0) // dunning 재시도 횟수\n  exemptFlag       Boolean            @default(false) // 운영자 수동 면제 (무기한 무료)\n  exemptNote       String?\n  provider         String? // \"toss\"\n  customerKey      String?            @unique // PG 구매자 식별 UUID\n\n  space Space              @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  items SubscriptionItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, currentPeriodEnd])\n}\n\n// 구독 라인아이템. type=DECK(현재) / ADDON(추후 확장).\nmodel SubscriptionItem {\n  id             String                 @id @default(cuid())\n  subscriptionId String\n  type           SubscriptionItemType   @default(DECK)\n  deckAppId      String\n  priceSnapshot  Int // 구독 시점 공급가 스냅샷\n  status         SubscriptionItemStatus @default(ACTIVE)\n  addedAt        DateTime               @default(now())\n  endedAt        DateTime?\n\n  subscription SpaceSubscription @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)\n\n  @@unique([subscriptionId, type, deckAppId])\n  @@index([subscriptionId, status])\n}\n\n// 결제수단 (빌링키). billingKey는 AES-256-CBC 암호화 보관.\nmodel BillingMethod {\n  id           String  @id @default(cuid())\n  spaceId      String\n  provider     String // \"toss\"\n  billingKey   String // 암호화 페이로드 (hex)\n  billingKeyIv String // hex iv\n  cardSummary  String? // \"신한 ****1234\" 표시용\n  isDefault    Boolean @default(true)\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([spaceId])\n}\n\n// 결제 이력. orderId 유니크 = 중복 결제 방지 멱등키.\nmodel BillingCharge {\n  id           String              @id @default(cuid())\n  spaceId      String\n  orderId      String              @unique // sub_{subId}_{yearMonth} | prorate_{itemId}\n  amount       Int // VAT 포함 결제액\n  supplyAmount Int // 공급가\n  vatAmount    Int\n  status       BillingChargeStatus @default(PENDING)\n  provider     String\n  paymentKey   String? // PG 결제 키\n  failReason   String?\n  periodStart  DateTime\n  periodEnd    DateTime\n  breakdown    Json // deck별 라인 [{deckAppId, price, type}]\n\n  space Space @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([spaceId, createdAt])\n  @@index([status])\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

